draftsim.py:
"""Draftsim-Tierlisten: wie Draftsim (draftsim.com) die Karten einschätzt, auf einer Skala von 0 bis 5.

Draftsim bewertet für jedes neue Set jede Karte für den Draft und pflegt eigene Listen für den
Vintage Cube und den Arena Powered Cube. Die Tabellen stecken in der Draft-App von Draftsim; das offene
Projekt „Argentum Engine“ (github.com/wingedsheep/argentum-engine) liest sie dort aus und legt sie als
JSON-Dateien ab. Von dort holt das Programm sie einmal pro Woche (ein Stand liegt bei: draftsim_start.json).

Wie die Wertungen einfließen (siehe generator.py):
  * Cube-Tierlisten (Vintage Cube, Arena Powered Cube): eine zweite Meinung zur Stärke im Cube, neben
    Draft-Elo und Vorbild-Cubes. Für Vintage-Cubes voll, für Commander zur Hälfte (die Listen sind für
    1 gegen 1 gedacht). Wertungen bis 1,5 zählen nicht: Das sind fast immer Kombo- und Spezialkarten
    (Show and Tell, Griselbrand, Dark Ritual, Bazaar of Baghdad …), die die Draftsim-Bots nicht spielen
    können – das ist kein Urteil über ihre Stärke.
  * Set-Tierlisten (Limited): nur für Karten, die noch kaum Draft-Elo haben, also vor allem Neuheiten,
    und nur ab 3,0 – dann hebt sie die geschätzte Stärke an, bis genug Cube-Drafts vorliegen. Nach unten
    zieht sie nie: Eine schwache Set-Wertung sagt über den Cube nichts (Commander-Karten oder Karten
    außerhalb der Booster stehen dort oft mit 0,7–1,0).
Nicht verwendet: Tabellen, die die Argentum-Leute für alte Sets selbst geschrieben haben (keine
Draftsim-Daten), und Länder (Limited-Wertungen sagen über Cube-Länder nichts).
"""
import json
import os
import re
import time
import unicodedata
import urllib.error
import urllib.request

from . import db

REPO = "wingedsheep/argentum-engine"
PFAD = "ai/src/main/resources/draftai/ratings"
ROH = "https://raw.githubusercontent.com/" + REPO + "/{ref}/" + PFAD + "/{datei}"
HERKUNFT = "https://raw.githubusercontent.com/" + REPO + "/{ref}/ai/src/main/kotlin/com/wingedsheep/ai/draftsim/DraftsimData.kt"
API = "https://api.github.com/repos/" + REPO + "/commits?path=" + PFAD + "&per_page=1"
START = os.path.join(os.path.dirname(os.path.abspath(__file__)), "draftsim_start.json")
USER_AGENT = "CubeGenerator/1.5 (privates Cube-Tool)"

CUBES = {"vintage_cube": "Vintage Cube", "arena_powered_cube": "Arena Powered Cube"}
# Tabellen, die nicht von Draftsim stammen (laut Argentum Engine selbst geschrieben). Beim Laden wird
# zusätzlich die Liste aus dem Quelltext des Projekts gelesen, falls dort neue dazukommen.
EIGENE = set("ATQ SCG LGN POR DOM MRD ONS INV BIG KHM ZNR M21 ELD LRW RAV CHK J22 LEA LEB LEG ARN DRK FEM "
             "PTK P02 S99 STX MAT PIP BLC NCC NEC C15 C17 CMD DDQ PZ2".split())
MINDEST_TABELLEN = 15        # weniger kann kein vollständiger Abruf sein – dann bleibt der alte Stand

# --- Wie stark die Wertungen zählen
CUBE_BODEN = 1.5             # bis hierher: Kombo-/Spezialkarte, die Draftsims Bots nicht spielen – kein Urteil
CUBE_MITTE = 2.8             # Mitte der Cube-Listen
CUBE_SPANNE = 1.4            # ab 4,2 voller Bonus
UNGELISTET = -0.5            # Vintage: in keiner Draftsim-Cube-Liste (−6 Punkte) …
UNGELISTET_VORBILD = 0.3     # … und in weniger als 30 % der Vorbild-Cubes; Neuheiten und Pflichtkarten ausgenommen
CUBE_MALUS = -0.35           # niedrige Wertungen kosten weniger: Draftsims Bots tun sich mit Cantrips, Blink und Kombos schwer
SET_GEWICHT = {"vintage": 0.5, "commander": 0.3}   # Anteil an der Stärke, solange es keine Draft-Elo gibt
SET_AB = 3.0                 # erst ab hier zählt die Set-Wertung (und dann nur nach oben)
ARCHITEKT_ANTEIL = 0.25      # so viel hebt eine bessere Draftsim-Erwartung die Einschätzung des Architekten an
# Set-Wertung → zu erwartendes Elo-Perzentil im Cube (gemessen an ~5.300 Karten mit verlässlicher Elo).
# Unter 2,5 ist die Kurve flach: Ob eine Karte im Set-Draft schwach oder sehr schwach ist, sagt für den Cube nichts.
SET_KURVE = [(0.0, 47.0), (2.5, 49.0), (3.0, 55.0), (3.5, 58.5), (4.0, 62.0), (4.5, 69.5), (5.0, 74.0)]


def schluessel(name):
    """Draftsims Namensschlüssel: Vorderseite, ohne Akzente, klein."""
    if not name:
        return ""
    s = unicodedata.normalize("NFD", str(name).split("//")[0])
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    s = s.replace("’", "'").replace("_", " ")
    return " ".join(s.lower().split())


# ------------------------------------------------------------------ Laden
def _holen(url, timeout=30, accept="application/json"):
    req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT, "Accept": accept})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read(8_000_000).decode("utf-8", "replace")


def _tabelle(text):
    """{name: wert} aus einer Ratings-Datei; prüft das Format streng (fremde Daten)."""
    d = json.loads(text)
    if not isinstance(d, dict):
        raise ValueError("keine Tabelle")
    out = {}
    for n, v in d.items():
        if isinstance(n, str) and 0 < len(n) <= 200 and isinstance(v, (int, float)) and not isinstance(v, bool) \
                and -2.0 <= v <= 6.0:
            out[schluessel(n)] = float(v)
    return out


def _eigene_aus_quelltext(text):
    """Set-Codes, die laut DraftsimData.kt selbst geschrieben sind (Abschnitt „Provenance“)."""
    m = re.search(r"\*\*Provenance\.\*\*(.*?)(?:\n \*\s*\n \* The vendored|\*/)", text, re.S)
    if not m:
        return set()
    absatz = m.group(1)
    # „(as `FRA`'s did)“ = inzwischen von Draftsim; „carried from `30A`“ = Quelle, nicht selbst geschrieben
    ersetzt = set(re.findall(r"as `([A-Z0-9]{2,6})`'s did", absatz)) | set(re.findall(r"from `([A-Z0-9]{2,6})`", absatz))
    return {c for c in re.findall(r"`([A-Z0-9]{2,6})`", absatz)} - ersetzt


def _speichern(con, tabellen, stand, quelle, commit=None):
    """tabellen: {quelle: {name: wert}} – quelle ist ein Set-Code oder vintage_cube / arena_powered_cube."""
    zeilen = [(n, q, w) for q, t in tabellen.items() for n, w in t.items()]
    if not zeilen:
        return 0
    con.execute("DELETE FROM draftsim")
    con.executemany("INSERT OR REPLACE INTO draftsim(name, quelle, wert) VALUES(?,?,?)", zeilen)
    db.meta_set(con, "draftsim_stand", stand)
    db.meta_set(con, "draftsim_quelle", quelle)
    db.meta_set(con, "draftsim_commit", commit or "")
    con.commit()
    return len({n for n, _, _ in zeilen})


def aus_start(con, erzwingen=False):
    """Mitgelieferten Stand übernehmen, wenn noch nichts da ist."""
    if not erzwingen and con.execute("SELECT 1 FROM draftsim LIMIT 1").fetchone():
        return 0
    if not os.path.exists(START):
        return 0
    with open(START, encoding="utf-8") as f:
        d = json.load(f)
    return _speichern(con, d["tabellen"], d.get("stand"), "mitgeliefert", d.get("commit"))


def laden(con, progress=None, pause=0.15):
    """Holt die aktuellen Tabellen. Hat sich im Projekt seit dem letzten Abruf nichts geändert, bleibt alles."""
    p = progress or (lambda *a: None)
    p("draftsim", 0, 0, "Stand prüfen")
    ref, stand = "main", time.strftime("%Y-%m-%d")
    try:
        c = json.loads(_holen(API, accept="application/vnd.github+json"))
        if c and isinstance(c, list):
            ref = str(c[0]["sha"])
            stand = str(c[0]["commit"]["committer"]["date"])[:10] or stand
    except (urllib.error.URLError, TimeoutError, OSError, ValueError, KeyError, IndexError):
        pass                                  # dann eben den aktuellen Stand ohne Vergleich holen
    if ref != "main" and ref == db.meta_get(con, "draftsim_commit") and con.execute("SELECT 1 FROM draftsim LIMIT 1").fetchone():
        db.meta_set(con, "draftsim_at", db.now())
        con.commit()
        return {"neu": False, "stand": db.meta_get(con, "draftsim_stand")}
    try:
        codes = json.loads(_holen(ROH.format(ref=ref, datei="_manifest.json")))
        codes = [str(x) for x in codes if isinstance(x, str) and re.fullmatch(r"[A-Z0-9]{2,8}", x)]
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
        raise RuntimeError(f"Die Draftsim-Tabellen sind gerade nicht erreichbar ({getattr(e, 'reason', e)}) – "
                           "es bleibt beim letzten Stand.") from None
    eigene = set(EIGENE)
    try:
        eigene |= _eigene_aus_quelltext(_holen(HERKUNFT.format(ref=ref), accept="text/plain"))
    except (urllib.error.URLError, TimeoutError, OSError, ValueError):
        pass
    dateien = list(CUBES) + [c for c in codes if c not in eigene]
    tabellen, fehler = {}, []
    for i, q in enumerate(dateien):
        p("draftsim", i, len(dateien), q)
        for versuch in range(2):
            try:
                t = _tabelle(_holen(ROH.format(ref=ref, datei=q + ".json")))
                if t:
                    tabellen[q] = t
                break
            except urllib.error.HTTPError as e:
                fehler.append(f"{q}: {e.code}")
                break
            except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
                if versuch:
                    fehler.append(f"{q}: {getattr(e, 'reason', e)}")
                time.sleep(1.0)
        time.sleep(pause)
    if len(tabellen) < MINDEST_TABELLEN or "vintage_cube" not in tabellen:
        raise RuntimeError(f"Nur {len(tabellen)} Draftsim-Tabellen geladen – es bleibt beim letzten Stand.")
    # Was diesmal nicht kam, bleibt beim alten Stand (statt aus der Bewertung zu verschwinden)
    for q in dateien:
        if q not in tabellen:
            alt = {n: w for n, w in con.execute("SELECT name, wert FROM draftsim WHERE quelle=?", (q,))}
            if alt:
                tabellen[q] = alt
    n = _speichern(con, tabellen, stand, "Draftsim (über Argentum Engine)", ref if ref != "main" else "")
    db.meta_set(con, "draftsim_at", db.now())
    con.commit()
    return {"neu": True, "karten": n, "sets": len([q for q in tabellen if q not in CUBES]),
            "cubes": len([q for q in tabellen if q in CUBES]), "stand": stand, "fehler": fehler}


# ------------------------------------------------------------------ Auswerten
def werte(con):
    """{Namensschlüssel: {"cube": {quelle: wert}, "set": {code: wert}}}"""
    out = {}
    try:
        for n, q, w in con.execute("SELECT name, quelle, wert FROM draftsim"):
            out.setdefault(n, {"cube": {}, "set": {}})["cube" if q in CUBES else "set"][q] = w
    except Exception:  # noqa: BLE001  (alte Datenbank ohne Tabelle)
        return {}
    return out


def entwirren(werte_, namen):
    """Draftsim legt Karten mit zwei Seiten unter beiden Namen ab. Heißt die Rückseite einer Karte so wie
    eine andere Karte (Emeritus of Ideation // Ancestral Recall), steht in derselben Liste unter dem Namen
    der anderen Karte womöglich der Wert der Doppelkarte. Gleicher Wert wie die Vorderseite = übernommen
    → für die andere Karte verwerfen. namen: alle Kartennamen der Datenbank."""
    rueck = {}
    for n in namen:
        if n and " // " in n:
            teile = n.split(" // ")
            for r in teile[1:]:
                rueck.setdefault(schluessel(r), set()).add(schluessel(teile[0]))
    for k, vorne in rueck.items():
        w = werte_.get(k)
        if not w:
            continue
        for v in vorne:
            andere = werte_.get(v)
            if not andere:
                continue
            for art in ("cube", "set"):
                for q in [q for q, x in w[art].items() if andere[art].get(q) == x]:
                    del w[art][q]
    return werte_


def fuer_karte(w):
    """Zusammengefasst: Ø der Cube-Listen und Ø der Set-Listen (eine Karte kann in mehreren Sets stehen)."""
    if not w:
        return None
    cube = sum(w["cube"].values()) / len(w["cube"]) if w["cube"] else None
    st = sum(w["set"].values()) / len(w["set"]) if w["set"] else None
    return {"cube": cube, "set": st, "cubes": dict(w["cube"]), "sets": dict(w["set"])}


def cube_signal(d, fmt):
    """-0,35 … +1 aus der Cube-Tierliste (None = keine verwertbare Wertung)."""
    if not d or d.get("cube") is None or d["cube"] <= CUBE_BODEN:
        return None
    s = max(CUBE_MALUS, min(1.0, (d["cube"] - CUBE_MITTE) / CUBE_SPANNE))
    return s * (0.5 if fmt == "commander" else 1.0)


def set_zu_power(wert):
    """Set-Wertung → geschätzte Stärke (0–100) im Cube."""
    w = max(SET_KURVE[0][0], min(SET_KURVE[-1][0], wert))
    for (a, pa), (b, pb) in zip(SET_KURVE, SET_KURVE[1:]):
        if a <= w <= b:
            return pa + (pb - pa) * (w - a) / (b - a)
    return SET_KURVE[-1][1]


def set_gewicht(fmt, elo_vertrauen):
    """Wie viel die Set-Wertung an der Stärke ausmacht: nichts bei verlässlicher Elo, sonst bis zu 50 % (Commander 30 %)."""
    return SET_GEWICHT["commander" if fmt == "commander" else "vintage"] * max(0.0, 1.0 - (elo_vertrauen or 0.0))


def bestenliste(con, n=40):
    """Für die Anzeige: die am höchsten bewerteten Karten der Cube-Listen."""
    zeilen = con.execute("SELECT name, AVG(wert) AS w FROM draftsim WHERE quelle IN (?, ?) GROUP BY name "
                         "ORDER BY w DESC LIMIT ?", (*CUBES, n)).fetchall()
    return [(r[0], round(r[1], 2)) for r in zeilen]


def als_start(con, pfad=START):
    """Aktuellen Stand als mitgelieferte Datei schreiben (für neue Versionen des Programms)."""
    tabellen = {}
    for n, q, w in con.execute("SELECT name, quelle, wert FROM draftsim ORDER BY quelle, name"):
        tabellen.setdefault(q, {})[n] = w
    with open(pfad, "w", encoding="utf-8") as f:
        json.dump({"stand": db.meta_get(con, "draftsim_stand"), "commit": db.meta_get(con, "draftsim_commit"),
                   "quelle": "Draftsim-Tabellen aus github.com/" + REPO, "tabellen": tabellen},
                  f, ensure_ascii=False, separators=(",", ":"))

edhrec.py:
"""EDHREC-Synergien: welche Karten und Themen zu einer legendären Kreatur passen.

Für jeden Commander zeigt EDHREC, welche Karten in seinen Decks auffällig oft liegen (Synergie =
wie viel häufiger als in anderen Decks seiner Farben) und welche Themen seine Decks haben
(z. B. Atraxa: Infect, +1/+1 Counters, Planeswalkers).

Der Generator nutzt das bei Commander-Cubes:
  * Sobald ein Commander im Cube ist, bekommen seine Synergie-Karten einen Bonus.
  * Ein Commander, für den schon viele passende Karten im Cube liegen, wird bevorzugt.
  * Ohne gewählte Themen helfen die EDHREC-Themen der beliebtesten Commander bei der Auswahl.
Geladen werden die beliebtesten Commander, alle legendären Kreaturen aus deinen gedruckten Cubes
und die aus dem zuletzt erzeugten Cube. Danach alle 30 Tage neu.
"""
import json
import re
import time
import unicodedata
import urllib.error
import urllib.request

from . import db, tagger

URL = "https://json.edhrec.com/pages/commanders/{slug}.json"
URL_THEMA = "https://json.edhrec.com/pages/tags/{slug}.json"
THEMA_MIN = 0.15             # ab dieser Synergie gehört eine Karte zum Thema
USER_AGENT = "CubeGenerator/1.2 (privates Cube-Tool)"
MIN_SYNERGIE = 0.05

def thema_zu():
    """EDHREC-Thema (slug) → Thema des Generators (steht in tagger.THEMEN bei „edhrec“)."""
    return tagger.edhrec_zu()


def slug(name):
    """Schreibweise von EDHREC: „Atraxa, Praetors' Voice“ → atraxa-praetors-voice"""
    s = db.front_face(name) or ""
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch)).lower()
    s = re.sub(r"[^a-z0-9\s-]", "", s)
    return re.sub(r"[\s-]+", "-", s).strip("-")


def _hole(name, timeout=30, url=None):
    req = urllib.request.Request(url or URL.format(slug=slug(name)), headers={"User-Agent": USER_AGENT, "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        if e.code in (403, 404):
            return None                      # kein Commander-Eintrag bei EDHREC
        raise


def speichern(con, key, data):
    jd = ((data or {}).get("container") or {}).get("json_dict") or {}
    karten = {}
    for liste in jd.get("cardlists") or []:
        for cv in liste.get("cardviews") or []:
            syn = cv.get("synergy")
            if not isinstance(syn, (int, float)) or syn < MIN_SYNERGIE or not cv.get("name"):
                continue
            k = db.resolve(con, cv["name"])
            if not k or k == key:
                continue
            anteil = (cv.get("num_decks") or 0) / max(1, cv.get("potential_decks") or 1)
            if k not in karten or karten[k][0] < syn:
                karten[k] = (float(syn), round(anteil, 4))
    themen = [(t.get("slug"), t.get("value"), int(t.get("count") or 0))
              for t in ((data or {}).get("panels") or {}).get("taglinks") or [] if t.get("slug")]
    decks = int(((jd.get("card") or {}).get("num_decks")) or 0)
    con.execute("DELETE FROM edh_synergie WHERE commander=?", (key,))
    con.execute("DELETE FROM edh_thema WHERE commander=?", (key,))
    con.executemany("INSERT INTO edh_synergie(commander, karte, synergie, anteil) VALUES(?,?,?,?)",
                    [(key, k, s, a) for k, (s, a) in karten.items()])
    con.executemany("INSERT OR IGNORE INTO edh_thema(commander, slug, name, anzahl) VALUES(?,?,?,?)",
                    [(key, s, v, n) for s, v, n in themen[:12]])
    con.execute("INSERT INTO edh_commander(key, stand, decks, ok) VALUES(?,?,?,?) ON CONFLICT(key) DO UPDATE SET "
                "stand=excluded.stand, decks=excluded.decks, ok=excluded.ok", (key, db.now(), decks, 1 if data else 0))
    return len(karten)


def kandidaten(con, beliebteste=450, extra=()):
    """Welche legendären Kreaturen geladen werden sollen (ohne schon frische)."""
    alt = db.now() - 30 * 86400
    legend = ("(lower(c.type_line) LIKE 'legendary%creature%' OR lower(c.oracle_text) LIKE '%can be your commander%')"
              " AND c.legal_commander = 1")
    keys = [r[0] for r in con.execute(f"SELECT c.key FROM cards c WHERE {legend} AND c.edhrec_rank IS NOT NULL "
                                      f"ORDER BY c.edhrec_rank LIMIT ?", (beliebteste,))]
    keys += [r[0] for r in con.execute(f"SELECT DISTINCT c.key FROM cards c JOIN vorrat v ON v.key = c.key WHERE {legend}")]
    keys += [k for k in extra if k]
    gesehen, out = set(), []
    for k in keys:
        if k in gesehen:
            continue
        gesehen.add(k)
        r = con.execute("SELECT stand FROM edh_commander WHERE key=?", (k,)).fetchone()
        if not r or (r[0] or 0) < alt:
            out.append(k)
    return out


def laden(con, keys, progress=None, pause=0.3, max_fehler=6):
    """Lädt die EDHREC-Seiten für die angegebenen Commander."""
    p = progress or (lambda *a: None)
    ok = 0
    fehler, leer = [], []
    for i, key in enumerate(keys):
        name = con.execute("SELECT name FROM cards WHERE key=?", (key,)).fetchone()
        if not name:
            continue
        p("edhrec", i, len(keys), name[0])
        try:
            data = _hole(name[0])
        except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
            fehler.append(f"{name[0]}: {getattr(e, 'reason', e)}")
            if len(fehler) >= max_fehler and not ok:
                raise RuntimeError("EDHREC ist gerade nicht erreichbar.") from None
            continue
        if data is None:
            # Keine Seite – oder EDHREC lässt uns gerade nicht rein. Erst merken, wenn andere Seiten klappen.
            leer.append(key)
            if not ok and len(leer) >= 8:
                raise RuntimeError("EDHREC liefert gerade keine Commander-Seiten. Später nochmal versuchen.")
        else:
            speichern(con, key, data)
            ok += 1
        if i % 20 == 0:
            con.commit()
        time.sleep(pause)
    if ok:
        for key in leer:
            speichern(con, key, None)
    con.commit()
    db.meta_set(con, "edhrec_at", db.now())
    con.commit()
    return {"geladen": ok, "ohne_eintrag": len(leer), "fehler": len(fehler)}


def synergien(con, keys):
    """{commander_key: {karte_key: synergie}} für die angegebenen Commander."""
    out = {}
    keys = list(keys)
    for i in range(0, len(keys), 500):
        teil = keys[i:i + 500]
        for r in con.execute(f"SELECT commander, karte, synergie FROM edh_synergie WHERE commander IN ({','.join('?' * len(teil))})", teil):
            out.setdefault(r[0], {})[r[1]] = r[2]
    return out


def themen(con, keys):
    """{commander_key: [(slug, name, anzahl)]}"""
    out = {}
    keys = list(keys)
    for i in range(0, len(keys), 500):
        teil = keys[i:i + 500]
        for r in con.execute(f"SELECT commander, slug, name, anzahl FROM edh_thema WHERE commander IN ({','.join('?' * len(teil))}) "
                             f"ORDER BY anzahl DESC", teil):
            out.setdefault(r[0], []).append((r[1], r[2], r[3]))
    return out


# ------------------------------------------------------------------ Themenseiten
def thema_speichern(con, tag, data):
    """Eine EDHREC-Themenseite: alle Karten mit Synergie (und die beliebtesten Commander des Themas)."""
    jd = ((data or {}).get("container") or {}).get("json_dict") or {}
    karten = {}
    for liste in jd.get("cardlists") or []:
        cmd = "commanders" in (liste.get("tag") or "")
        for cv in liste.get("cardviews") or []:
            syn = cv.get("synergy")
            if syn is None and cmd:
                syn = 0.3
            if not isinstance(syn, (int, float)) or syn < 0.1 or not cv.get("name"):
                continue
            k = db.resolve(con, cv["name"])
            if not k:
                continue
            anteil = (cv.get("num_decks") or 0) / max(1, cv.get("potential_decks") or 1)
            if k not in karten or karten[k][0] < syn:
                karten[k] = (round(float(syn), 4), round(anteil, 4), 1 if cmd else 0)
    con.execute("DELETE FROM edh_tag_karte WHERE slug=?", (tag,))
    con.executemany("INSERT INTO edh_tag_karte(slug, karte, synergie, anteil, commander) VALUES(?,?,?,?,?)",
                    [(tag, k, *w) for k, w in karten.items()])
    con.execute("INSERT INTO edh_tag(slug, stand, karten) VALUES(?,?,?) ON CONFLICT(slug) DO UPDATE SET "
                "stand=excluded.stand, karten=excluded.karten", (tag, db.now(), len(karten)))
    return len(karten)


def themen_laden(con, progress=None, pause=0.3):
    """Lädt die EDHREC-Seiten aller Themen, die der Generator kennt (rund 80 Seiten)."""
    p = progress or (lambda *a: None)
    slugs = sorted(thema_zu())
    ok, fehler = 0, []
    for i, tag in enumerate(slugs):
        p("edhrec_themen", i, len(slugs), tag)
        try:
            data = _hole(tag, url=URL_THEMA.format(slug=tag))
        except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
            fehler.append(tag)
            if len(fehler) >= 6 and not ok:
                raise RuntimeError("EDHREC ist gerade nicht erreichbar.") from None
            continue
        if data:
            thema_speichern(con, tag, data)
            ok += 1
        if i % 10 == 0:
            con.commit()
        time.sleep(pause)
    con.commit()
    if ok:
        db.meta_set(con, "edhrec_themen_at", db.now())
        con.commit()
    return {"geladen": ok, "fehler": len(fehler)}


def themen_karten(con, keys=None, mindest=THEMA_MIN):
    """{Karte: {Thema des Generators: Synergie}} aus den EDHREC-Themenseiten."""
    zu = thema_zu()
    out = {}
    sql = "SELECT slug, karte, synergie FROM edh_tag_karte WHERE synergie >= ?"
    try:
        zeilen = con.execute(sql, (mindest,)).fetchall()
    except Exception:  # noqa: BLE001  (alte Datenbank)
        return {}
    wahl = set(keys) if keys is not None else None
    for slug_, karte, sy in zeilen:
        if wahl is not None and karte not in wahl:
            continue
        t = zu.get(slug_)
        if t:
            d = out.setdefault(karte, {})
            if d.get(t, 0) < sy:
                d[t] = sy
    return out


def status(con):
    return {"commander": con.execute("SELECT COUNT(*) FROM edh_commander WHERE ok=1").fetchone()[0],
            "stand": db.meta_get(con, "edhrec_at")}

