CSV_SPALTEN = ["name", "CMC", "Type", "Color", "Set", "Collector Number", "Rarity", "Color Category",
               "status", "Finish", "board", "maybeboard", "image URL", "image Back URL", "tags", "Notes",
               "MTGO ID", "Custom", "Voucher", "Artist"]


def als_text(ergebnis):
    """Eine Karte pro Zeile – so nimmt der Massen-Import von CubeCobra sie an."""
    return "\n".join(k["name"] for k in ergebnis["karten"]) + "\n"


def als_csv(ergebnis):
    out = io.StringIO()
    w = csv.writer(out, quoting=csv.QUOTE_MINIMAL, lineterminator="\r\n")
