gespann.py:
"""Zwei Commander auf einmal: Partner, Partner with, Friends forever (bzw. „Partner—…“), Choose a Background mit
einem Background, Doctor's companion mit dem Doctor – und die Hausregel vieler Commander-Cubes:
Einfarbige Legenden haben automatisch Partner (zwei einfarbige Legenden ergeben also einen Zweifarben-Commander).

Die Fähigkeit steht als eigene Zeile im Regeltext; das Feld „keywords“ hilft nicht immer (manche Datenbanken
haben es leer), darum wird der Text gelesen.
"""
import re

from . import db

_ZEILE = re.compile(r"^\s*(partner with ([^(\n]+?)|partner\s*[—-]\s*([^(\n]+?)|partner|friends forever|choose a background|"
                    r"doctor.s companion)\s*(?:\(|$)", re.I | re.M)


def kann_commander(typ, text):
    """Legendäre Kreatur oder „can be your commander“ (manche Planeswalker)."""
    front = (typ or "").split("//")[0].lower()
    return ("legendary" in front and "creature" in front) or "can be your commander" in (text or "").lower()


def ist_background(typ):
    front = (typ or "").split("//")[0].lower()
    return "legendary" in front and "background" in front and "creature" not in front


def merkmale(name, text, typ, identitaet):
    """Liste kleiner Merkmale, aus denen sich ablesen lässt, mit wem eine Karte zusammen Commander sein darf:
    partner · mit:<name> · gruppe:<name> · cab · background · begleiter · doctor · mono"""
    out = []
    if ist_background(typ):
        return ["background"]
    if not kann_commander(typ, text):
        return out
    for m in _ZEILE.finditer(text or ""):
        ganz = m.group(1).lower()
        if m.group(2):
            out.append("mit:" + db.norm(m.group(2).strip()))
        elif m.group(3):
            out.append("gruppe:" + m.group(3).strip().lower())
        elif ganz == "partner":
            out.append("partner")
        elif ganz == "friends forever":
            out.append("gruppe:friends forever")
        elif ganz == "choose a background":
            out.append("cab")
        elif ganz.startswith("doctor"):
            out.append("begleiter")
    front = (typ or "").split("//")[0].lower()
    if "time lord doctor" in front:
        out.append("doctor")
    if len(identitaet or "") == 1:
        out.append("mono")
    return out


def passen(a_name, a, b_name, b, mono_regel=True):
    """Dürfen die beiden zusammen Commander sein? a, b: Merkmale aus merkmale()."""
    if a_name == b_name:
        return False
    a, b = set(a or ()), set(b or ())
    if not a or not b:
        return False
    if "background" in a and "background" in b:
        return False
    if ("cab" in a and "background" in b) or ("cab" in b and "background" in a):
        return True
    if "background" in a or "background" in b:
        return False
    partner_a = "partner" in a or (mono_regel and "mono" in a)
    partner_b = "partner" in b or (mono_regel and "mono" in b)
    if partner_a and partner_b:
        return True
    if "mit:" + db.norm(b_name) in a or "mit:" + db.norm(db.front_face(b_name)) in a:
        return True
    if "mit:" + db.norm(a_name) in b or "mit:" + db.norm(db.front_face(a_name)) in b:
        return True
    gruppen_a = {x for x in a if x.startswith("gruppe:")}
    if gruppen_a & b:
        return True
    if ("begleiter" in a and "doctor" in b) or ("begleiter" in b and "doctor" in a):
        return True
    return False


def offen(m, mono_regel=True):
    """Kann diese Karte (als einziger Commander) noch einen zweiten bekommen?"""
    m = set(m or ())
    return bool(m & {"partner", "cab", "begleiter", "doctor"}) or (mono_regel and "mono" in m) or \
        any(x.startswith(("mit:", "gruppe:")) for x in m)

handy.py:
"""Der Cube aufs iPhone und die Drafts zurück.

Aufs Handy: Ein Cube wird zu einem Paket (eine JSON-Datei) mit genau den Kartendaten, die die Bots auch am PC
nutzen. Die Datei landet im Ordner „handy“ neben dem Programm. Liegt das Programm in OneDrive, ist sie kurz
danach auf dem iPhone; die App liest sie über „Dateien“ ein.
Zurück: Die App speichert Drafts als Datei (…drafts.json) in denselben Ordner. Beim Start liest der Generator
sie ein: Sie erscheinen unter „Frühere Drafts“, und deine Picks fließen in die Bewertung ein (meine_picks.py).

Auf dem iPhone läuft dieselbe draft.py im Browser (Pyodide). aus_scryfall() baut dort die Kartendaten aus
Scryfall, wenn ein Cube nur als Namensliste kommt (z. B. ein gedruckter Cube ohne PC-Werte)."""
import json
import os
import re
import time

from . import aufraeumen, db, draft, generator, gespann, power, scryfall, tagger

ORDNER = os.path.join(db.BASE, "handy")
ART_CUBE = "cubegen-cube"
ART_DRAFTS = "cubegen-drafts"
ART_KARTEN = "cubegen-karten"
# Was die App von jeder Karte braucht, um daraus Cubes zu bauen und zu draften (wie generator.lade_karten())
DB_FELDER = ("key", "name", "mana_cost", "cmc", "type_line", "oracle_text", "colors", "color_identity", "keywords",
             "rarity", "set_code", "collector_number", "layout", "legal_commander", "legal_vintage", "legal_legacy",
             "legal_pauper", "edhrec_rank", "game_changer", "image_url", "image_back_url", "released_at", "erstdruck",
             "source", "elo", "picks", "power_manual", "salt", "ref_v", "ref_c", "vorrat", "besitz", "tags",
             "edh_themen", "turnier_w", "bot_w", "ds_w", "mein_w")
FARBEN = "WUBRG"


def _slug(name, fmt):
    s = re.sub(r"[^a-z0-9]+", "-", (name or "cube").lower()).strip("-") or "cube"
    return f"{s}-{fmt}"


# ------------------------------------------------------------------ PC: Cube als Paket
def paket(con, quelle):
    """Alles, was die App für einen Draft braucht – wie draft.neu() es am PC vorbereitet."""
    namen, name, fmt = draft._namen_fuer(con, quelle)
    karten, unbekannt = draft._lade(con, namen, fmt)
    vor = {}
    if quelle == "letzter" and os.path.exists(draft.LETZTER_CUBE):
        with open(draft.LETZTER_CUBE, encoding="utf-8") as f:
            vor = json.load(f)
    holo = set(vor.get("holo") or ())
    for k in karten:
        k["holo"] = k["name"] in holo
    groesse = int(vor.get("booster_groesse") or (20 if fmt == "commander" else 15))
    return {
        "art": ART_CUBE, "v": 1, "id": _slug(name, fmt), "name": name, "format": fmt, "zeit": time.time(),
        "quelle": "gedruckt" if quelle.startswith("vorrat:") else "erzeugt",
        "spieler": int(vor.get("spieler") or 8), "runden": int(vor.get("booster_pro_spieler") or 3), "groesse": groesse,
        "mono": vor.get("partner_mono", True), "themen": vor.get("themen") or [], "staemme": vor.get("staemme") or [],
        "archetypen": vor.get("archetypen") or {}, "karten": karten, "syn": draft._synergien(con, karten, fmt),
        "unbekannt": unbekannt[:50],
    }


def paket_speichern(p):
    os.makedirs(ORDNER, exist_ok=True)
    pfad = os.path.join(ORDNER, f"{draft.dateiname(p['name'])} ({'Commander' if p['format'] == 'commander' else 'Vintage'}).cube.json")
    with open(pfad + ".tmp", "w", encoding="utf-8") as f:
        json.dump(p, f, ensure_ascii=False, separators=(",", ":"))
    os.replace(pfad + ".tmp", pfad)
    return pfad


# ------------------------------------------------------------------ PC: Drafts vom Handy
def einlesen(con, protokoll=None):
    """Liest …drafts.json aus dem Ordner „handy“: neue Drafts kommen in die Draft-Liste, fertige zählen für die
    Bewertung. Eingelesene Dateien wandern nach handy/eingelesen. → {"dateien", "neu", "aktualisiert", "picks"}"""
    from . import meine_picks
    erg = {"dateien": 0, "neu": 0, "aktualisiert": 0, "picks": 0}
    if not os.path.isdir(ORDNER):
        return erg
    for n in sorted(os.listdir(ORDNER)):
        if not n.lower().endswith(".drafts.json"):
            continue
        pfad = os.path.join(ORDNER, n)
        try:
            with open(pfad, encoding="utf-8") as f:
                d = json.load(f)
            if d.get("art") != ART_DRAFTS:
                raise ValueError("keine Draft-Datei der App")
            for z in d.get("drafts") or []:
                if not isinstance(z, dict) or not z.get("id") or not isinstance(z.get("karten"), dict):
                    continue
                z["handy"] = True
                try:
                    alt = draft.laden(z["id"])
                except ValueError:
                    alt = None
                if alt is None or len(alt.get("log") or []) < len(z.get("log") or []) or (z.get("mein_deck") and not alt.get("mein_deck")):
                    draft.speichern(z)
                    erg["neu" if alt is None else "aktualisiert"] += 1
                erg["picks"] += meine_picks.einlesen(con, z)
            ziel = os.path.join(ORDNER, "eingelesen")
            os.makedirs(ziel, exist_ok=True)
            os.replace(pfad, os.path.join(ziel, n))
            erg["dateien"] += 1
        except (OSError, ValueError) as e:
            if protokoll:
                protokoll(f"Handy-Datei {n} nicht lesbar: {e}")
    return erg


# ------------------------------------------------------------------ iPhone: Kartendaten aus Scryfall
def _seite(c, i=0):
    f = c.get("card_faces") or []
    return f[i] if len(f) > i else {}


def _bild(c, i=0):
    u = c.get("image_uris") if i == 0 else None
    if not u:
        u = _seite(c, i).get("image_uris")
    return (u or {}).get("normal")


def _farben(liste):
    return "".join(f for f in FARBEN if f in (liste or []))


def _staerke(c, fmt):
    """Powerwert ohne Draft-Elo: aus dem EDHREC-Rang. Karten, die in Commander gebannt sind, haben keinen Rang –
    in Vintage sind das meist die stärksten Karten überhaupt (Power Nine, Moxe)."""
    p = power.power(None, None, c.get("edhrec_rank"), bool(c.get("game_changer")), 0.0)
    leg = c.get("legalities") or {}
    if fmt != "commander" and leg.get("commander") == "banned" and leg.get("vintage") in ("legal", "restricted"):
        p = max(p or 0, 92.0 if leg.get("vintage") == "restricted" else 84.0)
    elif fmt != "commander" and leg.get("vintage") == "restricted":
        p = max(p or 0, 88.0)
    return p


def aus_scryfall(karten_sf, fmt, bekannt=None):
    """Scryfall-Karten → Kartendaten wie draft._lade(). bekannt: {Name: Kartendaten vom PC} – die gelten dann."""
    bekannt = bekannt or {}
    skala = power.EloSkala([])
    out = []
    for i, c in enumerate(karten_sf):
