            "farben": z["colors"], "identitaet": z["color_identity"], "fach": generator.fach(z, fmt),
            "bild": _bild(c), "bild_rueck": _bild(c, 1) if seiten and not c.get("image_uris") else None,
            "seltenheit": c.get("rarity") or "", "set": (c.get("set") or "").upper(),
            "wert": round(draft._pickwert(z, p, 0.0, skala, fmt), 4), "power": None if p is None else round(p),
            "vorbild": 0, "kreatur": "creature" in front, "land": land,
            "land_farben": draft._land_farben(z) if land else "",
            "legendaer": gespann.kann_commander(z["type_line"], text), "background": gespann.ist_background(z["type_line"]),
            "gespann": gespann.merkmale(name, text, z["type_line"], z["color_identity"]),
            "rollen": sorted(t for t in tags if t in ("removal", "draw", "ramp", "counter", "wipe", "fixing", "recursion")),
            "themen": sorted(t for t in tags if t in tagger.THEMEN),
