    return out


# ------------------------------------------------------------------ Alle Karten aufs iPhone
def _knapp(z):
    """Leere Felder weglassen – die Datei wird so etwa halb so groß."""
    return {f: z[f] for f in DB_FELDER if z.get(f) not in (None, "", [], {}, set())}


def datenbank(con):
    """PC: die ganze Kartendatenbank so, wie der Generator sie liest – mit Elo, Vorbild-Cubes, Bot-Wertung,
    Draftsim, Deinen Picks und gedruckten Cubes. Dazu die Listen (zu stark, gesperrt, Pflicht)."""
    zeilen = []
    for r in generator.lade_karten(con):
        if "basic land" in (r.get("type_line") or "").lower():
            continue
        z = _knapp(r)
        z["tags"] = sorted(r.get("tags") or ())
        zeilen.append(z)
    listen = {n: generator.lese_liste(n + ".txt") for n in ("zu_stark", "sperre", "pflicht")}
    return {"art": ART_KARTEN, "v": 1, "quelle": "pc", "stand": time.time(), "anzahl": len(zeilen), "listen": listen,
            "zeilen": zeilen}


def datenbank_speichern(d):
    os.makedirs(ORDNER, exist_ok=True)
    pfad = os.path.join(ORDNER, "Alle Karten.karten.json")
    with open(pfad + ".tmp", "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, separators=(",", ":"))
    os.replace(pfad + ".tmp", pfad)
    return pfad


def zeilen_aus_scryfall(karten_sf):
    """iPhone ohne PC: Scryfall-Karten → Zeilen wie in der Datenbank am PC, mit denselben Regeln aussortiert
    (keine Spaßkarten, Tokens, Standardländer …) und mit denselben Themen und Rollen."""
    heute = time.strftime("%Y-%m-%d")
    out = []
    for c in karten_sf:
        if c.get("object") != "card" or aufraeumen.grund_karte(c, heute):
            continue
        z = scryfall.card_row(c)
        if not z or "basic land" in (z.get("type_line") or "").lower():
            continue
        # Scryfall zeigt meist den neuesten Druck. Ist er ein Nachdruck, ist die Karte keine Neuheit
        z["erstdruck"] = "2000-01-01" if c.get("reprint") else z.get("released_at")
        z["tags"] = sorted({t for t, _ in tagger.tags_for(z)})
        leg = c.get("legalities") or {}
        if not z.get("edhrec_rank") and leg.get("commander") == "banned" and leg.get("vintage") in ("legal", "restricted"):
            # in Commander gebannt, darum ohne EDHREC-Rang – in Vintage meist das Stärkste überhaupt
            z["power_manual"] = 92 if leg.get("vintage") == "restricted" else 84
        out.append(_knapp(z))
    return out


class Bestand:
    """iPhone: die Kartendatenbank der App im Speicher – zum Cube-Bauen (generator.py) und Draften (draft.py)."""

    def __init__(self, zeilen, listen=None):
        self.zeilen = []
        for z in zeilen:
            z = dict(z)
            for f in DB_FELDER:
                z.setdefault(f, None)
            z["tags"] = set(z.get("tags") or ())
            z["edh_themen"] = z.get("edh_themen") or {}
            z["source"] = z.get("source") or "scryfall"
            for f in ("legal_commander", "legal_vintage", "legal_legacy", "legal_pauper", "game_changer"):
                z[f] = z[f] or 0
            self.zeilen.append(z)
        self.nach_key = {z["key"]: z for z in self.zeilen}
        self.index = {}
        for z in self.zeilen:
            self.index.setdefault(db.norm(z["name"]), z["key"])
            self.index.setdefault(db.norm(db.front_face(z["name"])), z["key"])
        self.skala = power.EloSkala([(z["elo"], z.get("picks")) for z in self.zeilen if z.get("elo") is not None])
        self.listen = listen or {}
        if listen:
            os.makedirs(db.LIST_DIR, exist_ok=True)
            for n, l in listen.items():
                with open(os.path.join(db.LIST_DIR, n + ".txt"), "w", encoding="utf-8") as f:
                    f.write("\n".join(l))

    def finde(self, name):
        return self.index.get(db.norm(name)) or self.index.get(db.norm(db.front_face(name)))

    def draft_karten(self, namen, fmt):
        keys, unbekannt = [], []
        for n in namen:
            k = self.finde(n)
            (keys.append(k) if k else unbekannt.append(n))
        zeilen = {k: self.nach_key[k] for k in set(keys)}
        tags = {k: z["tags"] for k, z in zeilen.items()}
        tur = {k: z.get("turnier_w") for k, z in zeilen.items()}
        return draft.karten_aus_zeilen(keys, zeilen, tags, {}, tur, self.skala, fmt), unbekannt

    def cube(self, optionen):
        """Einen Cube bauen – derselbe Generator wie am PC, nur ohne Bot-Test und EDHREC-Synergien."""
        o = dict(optionen)
        o["bot_test"] = False
        o.setdefault("pflicht", self.listen.get("pflicht") or [])
        o.setdefault("sperre", self.listen.get("sperre") or [])
        erg = generator.erzeuge(None, o, karten=self.zeilen)
        if not erg.get("ok"):
            raise ValueError(erg.get("fehler") or "Der Cube ließ sich nicht bauen.")
        oo = erg["optionen"]
        fmt = oo["format"]
        karten, _ = self.draft_karten([k["name"] for k in erg["karten"]], fmt)
        holo = {k["name"] for k in erg["karten"] if k.get("holo")}
        for k in karten:
            k["holo"] = k["name"] in holo
        name = oo.get("name") or "Neuer Cube"
        return {
            "art": ART_CUBE, "v": 1, "id": f"{_slug(name, fmt)}-{int(time.time())}", "name": name, "format": fmt,
            "zeit": time.time(), "quelle": "auf dem iPhone gebaut", "spieler": oo["spieler"],
            "runden": oo["booster_pro_spieler"], "groesse": oo["booster_groesse"], "mono": oo.get("partner_mono", True),
            "themen": erg.get("cube_themen") or [], "staemme": erg.get("cube_staemme") or [],
            "archetypen": erg.get("archetypen") or {}, "karten": karten, "syn": {},
            "statistik": {"power": erg["statistik"].get("power_schnitt"), "holo": len(holo),
                          "themen": erg["statistik"].get("auto_themen") or []},
            "warnungen": (erg.get("warnungen") or [])[:3],
        }

imports.py:
"""Importe: CubeCobra-CSV, Elo-Werte, eigene Wertungen und die bestehende Datenbank."""
import csv
import io
import json
import re
import sqlite3
import urllib.error
import urllib.request

from . import db, tagger

TYP_ERSATZ = re.compile(r"\s+-\s+")


def _lies_csv(text):
    text = text.lstrip("﻿")
    kopf = text.split("\n", 1)[0]
    if kopf.count(",") >= max(1, kopf.count(";"), kopf.count("\t")):
        dialect = csv.excel                      # CubeCobra & Co.: Komma
    else:
        try:
            dialect = csv.Sniffer().sniff(text[:4096], delimiters=",;\t")
        except csv.Error:
            dialect = csv.excel
    return list(csv.DictReader(io.StringIO(text), dialect=dialect))


def _spalte(row_keys, *kandidaten):
    lk = {k.lower().strip(): k for k in row_keys if k}
    for c in kandidaten:
        if c in lk:
            return lk[c]
    for c in kandidaten:
        for k_low, k in lk.items():
            if c in k_low:
                return k
    return None


def _float(x):
    try:
        return float(str(x).replace(",", "."))
    except (TypeError, ValueError):
        return None


# ------------------------------------------------------------------ CubeCobra-CSV
def _csv_spalten(keys):
    return {
        "name": _spalte(keys, "name"), "cmc": _spalte(keys, "cmc"), "typ": _spalte(keys, "type"),
        "farbe": _spalte(keys, "color"), "set": _spalte(keys, "set"), "nr": _spalte(keys, "collector number"),
        "rar": _spalte(keys, "rarity"), "stat": _spalte(keys, "status"), "fin": _spalte(keys, "finish"),
        "img": _spalte(keys, "image url"),
    }


def _karte_sicherstellen(con, r, sp, jetzt):
    """Sucht die Karte; gibt es sie noch nicht, wird sie mit den Angaben aus der CSV angelegt.
    Rückgabe: (key, neu_angelegt)."""
    name = (r.get(sp["name"]) or "").strip()
    key = db.resolve(con, name)
    if key:
        return key, False
    key = db.norm(name)
    farbe = "".join(x for x in "WUBRG" if x in (r.get(sp["farbe"]) or "").upper())
    typ = TYP_ERSATZ.sub(" — ", (r.get(sp["typ"]) or "").strip())
    con.execute(
        "INSERT OR IGNORE INTO cards(key,name,cmc,type_line,oracle_text,colors,color_identity,keywords,"
        "rarity,set_code,collector_number,image_url,source,updated_at,legal_commander,legal_vintage,"
        "legal_legacy,legal_pauper) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,1,1,0)",
        (key, name, _float(r.get(sp["cmc"])) or 0, typ, "", farbe, farbe, "",
         (r.get(sp["rar"]) or "").lower(), (r.get(sp["set"]) or "").lower(), r.get(sp["nr"]) or "",
         (r.get(sp["img"]) or "") or None, "csv", jetzt))
    db.add_aliases(con, key, name)
    for tag, kind in tagger.tags_for({"name": name, "type_line": typ, "oracle_text": "", "keywords": ""}):
        con.execute("INSERT OR IGNORE INTO tags(key,tag,kind) VALUES(?,?,?)", (key, tag, kind))
    return key, True


def cubecobra_csv(con, text, als_pool=False, quelle="CubeCobra-CSV", als_vorrat=False):
    """Liest eine CubeCobra-CSV. Übernimmt den Besitzstatus und legt Karten,
    die noch nicht in der Datenbank sind, mit den Grunddaten aus der CSV an.
    als_vorrat: alle Karten der Liste sind gedruckt und liegen bereit (Status egal)."""
    rows = _lies_csv(text)
    if not rows:
        return {"zeilen": 0, "gefunden": 0, "neu": 0}
    sp = _csv_spalten(rows[0].keys())
    if not sp["name"]:
        raise ValueError("Keine Spalte „name“ in der CSV gefunden.")
    gefunden = neu = 0
    jetzt = db.now()
    if als_vorrat:
        con.execute("DELETE FROM vorrat WHERE quelle=?", (quelle,))
    for r in rows:
        if not (r.get(sp["name"]) or "").strip():
            continue
        key, ist_neu = _karte_sicherstellen(con, r, sp, jetzt)
        neu += ist_neu
        gefunden += not ist_neu
        if sp["stat"] and not als_vorrat:
            con.execute(
                "INSERT INTO collection(key,status,finish,source,imported_at) VALUES(?,?,?,?,?) "
                "ON CONFLICT(key) DO UPDATE SET status=excluded.status, finish=excluded.finish, "
                "source=excluded.source, imported_at=excluded.imported_at",
                (key, (r.get(sp["stat"]) or "").strip(), (r.get(sp["fin"]) or "").strip(), quelle, jetzt))
        if als_vorrat:
            con.execute("INSERT INTO vorrat(key,quelle,anzahl) VALUES(?,?,1) "
                        "ON CONFLICT(key,quelle) DO UPDATE SET anzahl=anzahl+1", (key, quelle))
        if als_pool:
            con.execute("INSERT OR IGNORE INTO pool(key,source) VALUES(?,?)", (key, quelle))
    con.commit()
    db.zusammenfuehren(con)
    return {"zeilen": len(rows), "gefunden": gefunden, "neu": neu}


def vorrat_csv(con, text, quelle):
    """Eine Liste gedruckter Karten (z. B. ein fertiger Cube) als Vorrat übernehmen."""
    return cubecobra_csv(con, text, quelle=quelle, als_vorrat=True)


def vorrat_entfernen(con, quelle):
    n = con.execute("DELETE FROM vorrat WHERE quelle=?", (quelle,)).rowcount
    con.commit()
    return n


def vorrat_ordner(con, ordner=None):
    """Liest alle CSV-Dateien aus dem Ordner „vorrat“ ein – aber nur, wenn sie neu sind oder sich
    geändert haben. Der Dateiname (ohne .csv) wird zum Namen der Liste. Ist eine Datei
    verschwunden, wird ihr Vorrat wieder entfernt."""
    import hashlib
    import os
    ordner = ordner or db.VORRAT_DIR
    bisher = json.loads(db.meta_get(con, "vorrat_ordner", "{}") or "{}")
    jetzt = {}
    erg = []
    if os.path.isdir(ordner):
        for datei in sorted(os.listdir(ordner)):
            if not datei.lower().endswith(".csv"):
                continue
            with open(os.path.join(ordner, datei), "rb") as f:
                roh = f.read()
            h = hashlib.sha1(roh).hexdigest()
            quelle = os.path.splitext(datei)[0]
            jetzt[quelle] = h
            if bisher.get(quelle) == h:
                continue
            r = vorrat_csv(con, roh.decode("utf-8-sig", errors="replace"), quelle)
            erg.append({"quelle": quelle, **r})
    for quelle in set(bisher) - set(jetzt):
        vorrat_entfernen(con, quelle)
        erg.append({"quelle": quelle, "entfernt": True})
    db.meta_set(con, "vorrat_ordner", json.dumps(jetzt))
    con.commit()
    return erg


# ------------------------------------------------------------------ Elo
# CubeCobra-Kartensuche als CSV: alle Karten, die mindestens einmal gepickt wurden.
# Spalten: Name, CMC, Type, Color, Set, Collector Number, Rarity, Elo, Total Picks, Cube Count
CUBECOBRA_ELO_URL = "https://cubecobra.com/tool/searchcards/csv?f=picks%3E0&s=Elo&d=descending&di=names"
CUBECOBRA_CUBE_URL = "https://cubecobra.com/cube/api/cubeJSON/{cid}"
EDHREC_SALT_URL = "https://json.edhrec.com/pages/{pfad}"
USER_AGENT = "CubeGenerator/0.2 (privates Cube-Tool)"


def _int(x):
    f = _float(x)
    return None if f is None else int(f)


def elo_csv(con, text, quelle="Elo-Datei", nur_eigene_quelle=False):
    """CSV mit einer Namens- und einer Elo-Spalte (Trennzeichen egal).
    Erkennt auch die CubeCobra-Kartensuche mit „Total Picks“ und „Cube Count“."""
    rows = _lies_csv(text)
    if not rows:
        return {"zeilen": 0, "uebernommen": 0, "unbekannt": []}
    keys = rows[0].keys()
    c_name = _spalte(keys, "name", "karte", "card")
    c_elo = _spalte(keys, "elo", "rating")
    if not c_name or not c_elo:
        raise ValueError("Die Datei braucht eine Spalte „name“ und eine Spalte „elo“.")
    c_picks = _spalte(keys, "total picks", "pickcount", "pick count", "picks")
    c_cubes = _spalte(keys, "cube count", "cubecount", "cubes")
    eintraege = [(r.get(c_name), _float(r.get(c_elo)),
                  _int(r.get(c_picks)) if c_picks else None,
                  _int(r.get(c_cubes)) if c_cubes else None) for r in rows]
    return _elo_speichern(con, eintraege, quelle, nur_eigene_quelle)


def _elo_speichern(con, eintraege, quelle, nur_eigene_quelle=False):
    """eintraege: (name, elo[, picks[, cube_count]]).
    nur_eigene_quelle: automatische Abrufe überschreiben keine Elo aus deinen eigenen Dateien."""
    jetzt = db.now()
    ok, unbekannt, gesehen = 0, [], set()
    bedingung = (" WHERE ratings.elo_source IS NULL OR ratings.elo_source LIKE 'CubeCobra%'"
                 if nur_eigene_quelle else "")
    sql = ("INSERT INTO ratings(key,elo,elo_source,elo_updated,picks,cube_count) VALUES(?,?,?,?,?,?) "
           "ON CONFLICT(key) DO UPDATE SET elo=excluded.elo, elo_source=excluded.elo_source, "
           "elo_updated=excluded.elo_updated, picks=excluded.picks, cube_count=excluded.cube_count" + bedingung)
    for e in eintraege:
        name, elo = e[0], e[1]
        picks = e[2] if len(e) > 2 else None
        cubes = e[3] if len(e) > 3 else None
        if not name or elo is None:
            continue
        key = db.resolve(con, name)
        if not key:
            unbekannt.append(name)
            continue
        if key in gesehen:          # gleiche Karte doppelt (z.B. zwei Schreibweisen): erste zählt
            continue
        gesehen.add(key)
        con.execute(sql, (key, elo, quelle, jetzt, picks, cubes))
        ok += 1
    db.meta_set(con, "elo_loaded_at", jetzt)
    con.commit()
    return {"zeilen": len(eintraege), "uebernommen": ok, "unbekannt": unbekannt[:50], "unbekannt_anzahl": len(unbekannt)}


def finde_elo(obj, out=None):
    """Sucht in beliebig verschachteltem JSON nach Objekten mit Name und Elo
    (bei CubeCobra stecken sie in cards.mainboard[].details)."""
    if out is None:
        out = {}
    if isinstance(obj, dict):
        name = obj.get("name")
        elo = obj.get("elo")
        if isinstance(name, str) and isinstance(elo, (int, float)):
            picks = obj.get("pickCount")
            cubes = obj.get("cubeCount")
            out[name] = (float(elo), picks if isinstance(picks, int) else None,
                         cubes if isinstance(cubes, int) else None)
        for v in obj.values():
            if isinstance(v, (dict, list)):
                finde_elo(v, out)
    elif isinstance(obj, list):
        for v in obj:
            finde_elo(v, out)
    return out


def _hole(url, was, timeout=120):
    """Lädt eine Adresse und übersetzt Netzfehler in verständliche Meldungen."""
    req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT, "Accept": "*/*"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read()
    except urllib.error.HTTPError as e:
        if e.code == 404:
            raise RuntimeError(f"{was}: nicht gefunden (404).") from None
        if e.code == 429:
            raise RuntimeError(f"{was}: zu viele Anfragen – bitte in ein paar Minuten noch einmal.") from None
        raise RuntimeError(f"{was} antwortet mit Fehler {e.code}.") from None
    except (urllib.error.URLError, TimeoutError, OSError) as e:
        raise RuntimeError(f"{was} ist nicht erreichbar ({getattr(e, 'reason', e)}). "
                           f"Internetverbindung prüfen.") from None


def elo_cubecobra(con, cube_id):
    """Elo-Werte der Karten eines einzelnen öffentlichen CubeCobra-Cubes."""
    cid = cube_id.strip().rstrip("/").split("/")[-1].split("?")[0]
    roh = _hole(CUBECOBRA_CUBE_URL.format(cid=cid), f"CubeCobra-Cube „{cid}“", timeout=60)
    try:
        data = json.loads(roh.decode("utf-8"))
    except ValueError:
        raise RuntimeError("CubeCobra hat keine lesbare Cube-Datei geliefert.") from None
    paare = finde_elo(data)
    if not paare:
        return {"zeilen": 0, "uebernommen": 0, "unbekannt": [],
                "hinweis": "In der Cube-Datei von CubeCobra waren keine Elo-Werte enthalten."}
    return _elo_speichern(con, [(n, *w) for n, w in paare.items()], f"CubeCobra {cid}", nur_eigene_quelle=True)


def elo_cubecobra_alle(con, progress=None):
    """Holt die Elo aller Karten aus der CubeCobra-Kartensuche (eine CSV, ca. 2–4 MB)."""
    p = progress or (lambda *a: None)
    p("elo_download", 0, 0)
    roh = _hole(CUBECOBRA_ELO_URL, "CubeCobra", timeout=300)
    text = roh.decode("utf-8", errors="replace")
    if not text.lstrip("\ufeff").lower().startswith("name,"):
        raise RuntimeError("CubeCobra hat keine Kartenliste geliefert (Format geändert?). "
                           "Notfalls auf cubecobra.com/tool/searchcards „Download CSV“ klicken und die Datei importieren.")
    p("elo_import", 0, 0)
    erg = elo_csv(con, text, quelle="CubeCobra (alle Karten)", nur_eigene_quelle=True)
    db.meta_set(con, "cubecobra_elo_at", db.now())
    con.commit()
    return erg


def salt_edhrec(con, progress=None, min_salt=1.0, max_seiten=60, pause=0.4):
    """Holt die Salt-Werte von EDHREC (wie sehr eine Karte am Tisch nervt, 0–4).
    Die Liste ist absteigend sortiert; geladen wird, bis der Wert unter min_salt fällt."""
    import time as _t
    p = progress or (lambda *a: None)
    pfad, seite, werte = "top/salt.json", 0, []
    while pfad and seite < max_seiten:
        p("salt", seite, 0)
        roh = _hole(EDHREC_SALT_URL.format(pfad=pfad), "EDHREC", timeout=60)
        try:
            data = json.loads(roh.decode("utf-8"))
        except ValueError:
            raise RuntimeError("EDHREC hat keine lesbare Salt-Liste geliefert.") from None
        if "cardviews" in data:
            liste, pfad = data.get("cardviews") or [], data.get("more")
        else:
            cl = (((data.get("container") or {}).get("json_dict") or {}).get("cardlists") or [{}])[0]
            liste, pfad = cl.get("cardviews") or [], cl.get("more")
        if not liste:
            break
        for cv in liste:
            if isinstance(cv.get("salt"), (int, float)) and cv.get("name"):
                werte.append((cv["name"], float(cv["salt"])))
        seite += 1
        if werte and werte[-1][1] < min_salt:
            break
        if pfad:
            _t.sleep(pause)
    if not werte:
        raise RuntimeError("EDHREC hat keine Salt-Werte geliefert.")
    con.execute("UPDATE ratings SET salt=NULL")
    ok, unbekannt = 0, []
    for name, salt in werte:
        key = db.resolve(con, name)
        if not key:
            unbekannt.append(name)
            continue
        con.execute("INSERT INTO ratings(key,salt) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET salt=excluded.salt",
                    (key, salt))
        ok += 1
    db.meta_set(con, "salt_at", db.now())
    con.commit()
    return {"seiten": seite, "zeilen": len(werte), "uebernommen": ok,
            "unbekannt": unbekannt[:30], "unbekannt_anzahl": len(unbekannt),
            "kleinster_wert": round(werte[-1][1], 2)}


# ------------------------------------------------------------------ eigene Wertung
def eigene_wertung(con, text):
    """Zeilen wie 'Grave Titan = 85' oder 'Sol Ring; 95'. Leerer Wert löscht die Wertung."""
    ok, unbekannt = 0, []
    for z in text.splitlines():
        z = z.split("#", 1)[0].strip()
        if not z:
            continue
        m = re.match(r"^(.*?)\s*[=;:\t]\s*(\d+(?:[.,]\d+)?)?\s*$", z)
        if not m:
            continue
        name, wert = m.group(1).strip(), _float(m.group(2)) if m.group(2) else None
        key = db.resolve(con, name)
        if not key:
            unbekannt.append(name)
            continue
        con.execute("INSERT INTO ratings(key,power_manual) VALUES(?,?) "
                    "ON CONFLICT(key) DO UPDATE SET power_manual=excluded.power_manual", (key, wert))
        ok += 1
    con.commit()
    return {"uebernommen": ok, "unbekannt": unbekannt}


def eigene_wertung_text(con):
    rows = con.execute("SELECT c.name, r.power_manual FROM ratings r JOIN cards c ON c.key=r.key "
                       "WHERE r.power_manual IS NOT NULL ORDER BY c.name").fetchall()
    return "\n".join(f"{r['name']} = {r['power_manual']:g}" for r in rows)


# ------------------------------------------------------------------ bestehende Datenbank
SPALTEN = {
    "name": ["name", "card_name", "cardname", "kartenname"],
    "type_line": ["type_line", "typeline", "type", "typ"],
    "oracle_text": ["oracle_text", "oracletext", "text", "rules_text"],
    "mana_cost": ["mana_cost", "manacost", "cost"],
    "cmc": ["cmc", "mana_value", "manavalue", "mv"],
    "colors": ["colors", "color", "farbe"],
    "color_identity": ["color_identity", "coloridentity", "identity"],
    "rarity": ["rarity", "seltenheit"],
    "edhrec_rank": ["edhrec_rank", "edhrecrank"],
    "elo": ["elo", "elo_rating"],
    "keywords": ["keywords"],
}


def _farben(x):
    if x is None:
        return ""
    s = str(x).upper()
    return "".join(c for c in "WUBRG" if c in s)


def analysiere_db(pfad):
    """Zeigt Tabellen und Spalten der fremden Datenbank (nur lesend)."""
    src = sqlite3.connect(f"file:{pfad}?mode=ro", uri=True)
    try:
        out = []
        for (t,) in src.execute("SELECT name FROM sqlite_master WHERE type='table'"):
            cols = [r[1] for r in src.execute(f'PRAGMA table_info("{t}")')]
            n = src.execute(f'SELECT COUNT(*) FROM "{t}"').fetchone()[0]
            out.append({"tabelle": t, "spalten": cols, "zeilen": n})
        return out
    finally:
        src.close()


def _zuordnung(cols):
    lc = {c.lower(): c for c in cols}
    z = {}
    for ziel, namen in SPALTEN.items():
        for n in namen:
            if n in lc:
                z[ziel] = lc[n]
                break
    return z


def pool_aus_db(con, pfad, tabelle=None, kartendaten=True):
    """Übernimmt die Karten aus deiner bestehenden SQLite als „Mein Pool“.

    Karten, die du dort aussortiert hast, sind damit automatisch nicht im Pool.
    Fehlen Kartendaten (Scryfall noch nicht geladen), werden Typ, Kosten, Farben
    und Text aus deiner Datenbank übernommen, soweit Spalten dafür da sind.
    Vorhandene Elo-Werte werden ebenfalls übernommen.
    """
    info = analysiere_db(pfad)
    if tabelle is None:
        mit_name = [t for t in info if _zuordnung(t["spalten"]).get("name")]
        if not mit_name:
            raise ValueError("In der Datenbank wurde keine Tabelle mit einer Namensspalte gefunden.")
        tabelle = max(mit_name, key=lambda t: t["zeilen"])["tabelle"]
    t = next(x for x in info if x["tabelle"] == tabelle)
    z = _zuordnung(t["spalten"])
    src = sqlite3.connect(f"file:{pfad}?mode=ro", uri=True)
    src.row_factory = sqlite3.Row
    jetzt = db.now()
    gefunden = neu = elo = 0
    try:
        con.execute("DELETE FROM pool WHERE source=?", (f"DB {tabelle}",))
        for r in src.execute(f'SELECT * FROM "{tabelle}"'):
            name = r[z["name"]]
            if not name:
                continue
            name = str(name).strip()
            key = db.resolve(con, name)
            if key:
                gefunden += 1
            elif kartendaten:
                key = db.norm(name)
                g = lambda f, d=None: r[z[f]] if f in z else d
                typ = TYP_ERSATZ.sub(" — ", str(g("type_line", "") or ""))
                con.execute(
                    "INSERT OR IGNORE INTO cards(key,name,mana_cost,cmc,type_line,oracle_text,colors,color_identity,"
                    "keywords,rarity,edhrec_rank,source,updated_at,legal_commander,legal_vintage,legal_legacy,legal_pauper)"
                    " VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,1,1,1,0)",
                    (key, name, g("mana_cost", "") or "", _float(g("cmc")) or 0, typ, g("oracle_text", "") or "",
                     _farben(g("colors")), _farben(g("color_identity") or g("colors")),
                     str(g("keywords", "") or ""), str(g("rarity", "") or "").lower(),
                     int(_float(g("edhrec_rank")) or 0) or None, "meinedb", jetzt))
                db.add_aliases(con, key, name)
                neu += 1
            else:
                continue
            con.execute("INSERT OR IGNORE INTO pool(key,source) VALUES(?,?)", (key, f"DB {tabelle}"))
            if "elo" in z and _float(r[z["elo"]]) is not None:
                con.execute("INSERT INTO ratings(key,elo,elo_source,elo_updated) VALUES(?,?,?,?) "
                            "ON CONFLICT(key) DO UPDATE SET elo=excluded.elo, elo_source=excluded.elo_source",
                            (key, _float(r[z["elo"]]), "meine Datenbank", jetzt))
                elo += 1
    finally:
        src.close()
    con.commit()
    if neu:
        tagger.rebuild(con)
    return {"tabelle": tabelle, "zuordnung": z, "gefunden": gefunden, "neu": neu, "elo": elo}

power.py:
"""Powerwert einer Karte (0-100).

Quellen, in dieser Rangfolge:
  1. eigene Wertung (power_manual) - schlägt alles
  2. Draft-Elo (CubeCobra) - wie hoch Spieler die Karte im Draft picken
  3. EDHREC-Rang aus den Scryfall-Daten - wie oft die Karte in Commander gespielt wird
Game Changer (offizielle Commander-Liste) werden mindestens auf 85 gesetzt.

Elo wird nicht als Rohzahl verwendet, sondern als Perzentil: 95 heißt
"besser gepickt als 95 % aller Karten mit verlässlicher Elo". So ist egal,
auf welcher Skala die Quelle rechnet. Elo von Karten, die kaum gepickt wurden,
ist wenig wert (alle starten bei 1200) und bekommt entsprechend weniger Gewicht.

Der EDHREC-Rang misst Beliebtheit, nicht Stärke. Er ist deshalb nur die
Rückfallebene; sobald verlässliche Elo-Werte vorliegen, bekommen diese das größere Gewicht.
"""
import bisect
import math

RANK_MAX = 25000.0
PICKS_MIN = 50       # darunter wird die Elo nicht verwendet
PICKS_VOLL = 500     # ab hier volles Vertrauen in die Elo
ELO_GEWICHT = 0.65
# Commander-Cubes: Die Draft-Elo stammt fast nur aus Vintage- und Legacy-Cubes. Was in Commander wirklich
# gespielt wird – auch frische Karten, sobald sie beliebt sind –, zeigt der EDHREC-Rang besser.
ELO_GEWICHT_COMMANDER = 0.3


def elo_gewicht(fmt):
    return ELO_GEWICHT_COMMANDER if fmt == "commander" else ELO_GEWICHT


def vertrauen(picks):
    """0..1 – wie verlässlich die Elo ist. Ohne Pick-Zahl (eigene Elo-Datei) = voll."""
    if picks is None:
        return 1.0
    if picks < PICKS_MIN:
        return 0.0
    return min(1.0, 0.3 + 0.7 * (picks - PICKS_MIN) / (PICKS_VOLL - PICKS_MIN))


class EloSkala:
    """Rechnet Elo in ein Perzentil (0-100) um, bezogen auf alle verlässlichen Werte."""

    def __init__(self, paare):
        self.werte = sorted(float(e) for e, picks in paare if e is not None and vertrauen(picks) > 0)

    def __len__(self):
        return len(self.werte)

    def perzentil(self, elo):
        if elo is None or not self.werte:
            return None
        n = len(self.werte)
        unter = bisect.bisect_left(self.werte, float(elo))
        gleich = bisect.bisect_right(self.werte, float(elo)) - unter
        return 100.0 * (unter + 0.5 * gleich) / n


def edh_score(rank):
    if not rank:
        return None
    r = max(1.0, float(rank))
    return max(0.0, min(100.0, 100.0 * (1.0 - math.log(r) / math.log(RANK_MAX))))


def power(manual=None, elo_perz=None, rank=None, game_changer=False, elo_vertrauen=1.0, gewicht=ELO_GEWICHT):
    """Kombinierter Powerwert oder None, wenn nichts bekannt ist. gewicht: Anteil der Elo (elo_gewicht(fmt))."""
    if manual is not None:
        return float(manual)
    e = elo_perz if (elo_perz is not None and elo_vertrauen > 0) else None
    r = edh_score(rank)
    if e is not None and r is not None:
        w = gewicht * elo_vertrauen
        p = w * e + (1.0 - w) * r
    elif e is not None:
        p = e
    else:
        p = r
    if game_changer:
        p = max(p or 0.0, 85.0)
    return p


def herkunft(manual=None, elo=None, rank=None, picks=None):
    if manual is not None:
        return "eigene Wertung"
    elo_ok = elo is not None and vertrauen(picks) > 0
    if elo_ok and rank:
        return "Elo + EDHREC"
    if elo_ok:
        return "Elo"
    if rank:
        return "EDHREC-Rang"
    return "unbekannt"

scryfall.py:
"""Scryfall: die komplette Scryfall-Datenbank holen und lokal ablegen.

Scryfall stellt seine Daten als Bulk-Dateien bereit (seit 2026 als JSON Lines,
gzip-komprimiert, Adresse im Feld "jsonl_download_uri"). Geladen werden:

  Karten          oracle_cards   jede Karte genau einmal, Grundlage für den Generator (Tabelle cards)
  Drucke          default_cards  jeder englische Druck jeder Karte mit ALLEN Scryfall-Feldern (Tabelle drucke)
  Funktions-Tags  oracle_tags    Scryfall-Tagger: was eine Karte tut (removal, ramp, sweeper ...)
  Bild-Tags       art_tags       Scryfall-Tagger: was auf dem Bild zu sehen ist (snow, beer, feast ...)
  Regelhinweise   rulings        offizielle Rulings je Karte

Jeder Druck wird vollständig gespeichert (Spalte json, zlib-komprimiert), dazu die
wichtigsten Felder als eigene Spalten zum schnellen Suchen. So geht von Scryfall
nichts verloren, auch Felder, die wir heute noch nicht brauchen.

Was für Cubes nichts taugt (Spaßkarten, Standardländer, Token, andere Sprachen ...),
wird beim Laden aussortiert, siehe aufraeumen.py.
"""
import base64
import contextlib
import gzip
import io
import itertools
import json
import os
import traceback
import urllib.error
import urllib.request
import zlib

from . import aufraeumen, db

API_BULK = os.environ.get("CUBEGEN_SCRYFALL_API", "https://api.scryfall.com/bulk-data")
HEADERS = {
    "User-Agent": "CubeGenerator/0.5 (privates Hobbyprojekt)",
    "Accept": "application/json;q=0.9,*/*;q=0.8",
}
SF_DIR = os.path.join(db.DATA_DIR, "scryfall")



# ================================================================ Herunterladen
def _get(url, timeout=60):
    req = urllib.request.Request(url, headers=HEADERS)
    return urllib.request.urlopen(req, timeout=timeout)


def bulk_liste():
    """Alle Bulk-Dateien, die Scryfall gerade anbietet: {typ: eintrag}."""
    with _get(API_BULK) as r:
        data = json.load(r)
    return {item.get("type"): item for item in data.get("data", [])}


def bulk_url(item):
    url = item.get("jsonl_download_uri") or item.get("download_uri")
    if not url:
        raise RuntimeError(f"Scryfall nennt für „{item.get('name') or item.get('type')}“ keine Download-Adresse "
                           f"(Felder: {', '.join(sorted(item))}). Vermutlich hat Scryfall das Format erneut geändert.")
    return url


def download(url, target, progress=None, groesse=0):
    """Lädt eine Datei so herunter, wie sie kommt (meist .jsonl.gz). progress(gelesen, gesamt)."""
    tmp = target + ".part"
    req = urllib.request.Request(url, headers=HEADERS)
    with urllib.request.urlopen(req, timeout=120) as r:
        total = int(r.headers.get("Content-Length") or 0) or int(groesse or 0)
        done = 0
        with open(tmp, "wb") as f:
            while True:
                chunk = r.read(1 << 20)
                if not chunk:
                    break
                f.write(chunk)
                done += len(chunk)
                if progress:
                    progress(done, total)
    os.replace(tmp, target)
    return target


# ================================================================ Lesen
def iter_json_array(fileobj, chunk_size=1 << 20):
    """Liest ein riesiges JSON-Array Objekt für Objekt (altes Scryfall-Format)."""
    import codecs
    dec = json.JSONDecoder()
    utf8 = codecs.getincrementaldecoder("utf-8")()
    buf = ""
    pos = 0
    started = False
    eof = False

    def more():
        nonlocal buf, pos, eof
        data = fileobj.read(chunk_size)
        if isinstance(data, bytes):
            data = utf8.decode(data, final=not data)
        if not data:
            eof = True
        buf = buf[pos:] + data
        pos = 0

    more()
    while True:
        n = len(buf)
        while pos < n and buf[pos] in " \t\r\n,﻿":
            pos += 1
        if pos >= n:
            if eof:
                return
            more()
            continue
        if not started:
            if buf[pos] == "[":
                started = True
                pos += 1
                continue
            raise ValueError("Datei beginnt nicht mit einem JSON-Array")
        if buf[pos] == "]":
            return
        try:
            obj, end = dec.raw_decode(buf, pos)
        except json.JSONDecodeError:
            if eof:
                raise
            more()  # Objekt reicht über die Chunk-Grenze: nachladen
            continue
        yield obj
        pos = end


class _MitAnfang:
    """Gibt erst einen bereits gelesenen Anfang zurück, dann den Rest der Datei."""

    def __init__(self, anfang, f):
        self.anfang, self.f = anfang, f

    def read(self, n=-1):
        if self.anfang:
            a, self.anfang = self.anfang, ""
            return a
        return self.f.read(n)


def eintraege(pfad):
    """Liefert (objekt, rohtext) für jede Zeile einer Scryfall-Datei.

    Erkennt selbst: gzip oder nicht (auch doppelt gepackt), JSON Lines oder JSON-Array."""
    with contextlib.ExitStack() as st:
        f = st.enter_context(open(pfad, "rb"))
        for _ in range(2):
            if f.peek(2)[:2] == b"\x1f\x8b":
                f = st.enter_context(gzip.GzipFile(fileobj=f))
            else:
                break
        txt = st.enter_context(io.TextIOWrapper(f, encoding="utf-8-sig", newline=""))
        anfang = txt.read(1)
        while anfang and anfang.isspace():
            anfang = txt.read(1)
        if not anfang:
            return
        if anfang == "[":
            for obj in iter_json_array(_MitAnfang("[", txt)):
                yield obj, None
            return
        zeile = anfang + txt.readline()
        while zeile:
            z = zeile.strip().rstrip(",")
            if z:
                yield json.loads(z), z
            zeile = txt.readline()


# ================================================================ Karten (Generator-Grundlage)
def _faces(card):
    return card.get("card_faces") or []


def card_row(c):
    """Wandelt ein Scryfall-Kartenobjekt in eine Zeile der Tabelle cards um (oder None)."""
    if c.get("object") != "card":
        return None
    if c.get("layout") == "reversible_card" or c.get("lang", "en") != "en":
        return None
    faces = _faces(c)
    name = c.get("name") or ""
    if not name:
        return None
    oracle = c.get("oracle_text")
    if oracle is None and faces:
        oracle = "\n//\n".join(f.get("oracle_text") or "" for f in faces)
    type_line = c.get("type_line")
    if not type_line and faces:
        type_line = " // ".join(f.get("type_line") or "" for f in faces)
    mana = c.get("mana_cost")
    if not mana and faces:
        mana = faces[0].get("mana_cost") or ""
    colors = c.get("colors")
    if colors is None and faces:
        colors = sorted({x for f in faces for x in (f.get("colors") or [])})
    img = (c.get("image_uris") or {}).get("normal")
    back = None
    if faces:
        if not img:
            img = (faces[0].get("image_uris") or {}).get("normal")
        if len(faces) > 1:
            back = (faces[1].get("image_uris") or {}).get("normal")
    leg = c.get("legalities") or {}
    ok = lambda f: 1 if leg.get(f) in ("legal", "restricted") else 0
    return {
        "key": db.norm(name),
        "name": name,
        "oracle_id": c.get("oracle_id") or (faces[0].get("oracle_id") if faces else None),
        "mana_cost": mana or "",
        "cmc": float(c.get("cmc") or 0),
        "type_line": type_line or "",
        "oracle_text": oracle or "",
        "colors": "".join(x for x in "WUBRG" if x in (colors or [])),
        "color_identity": "".join(x for x in "WUBRG" if x in (c.get("color_identity") or [])),
        "keywords": ",".join(c.get("keywords") or []),
        "rarity": c.get("rarity") or "",
        "set_code": c.get("set") or "",
        "collector_number": c.get("collector_number") or "",
        "layout": c.get("layout") or "",
        "legal_commander": 1 if leg.get("commander") == "legal" else 0,
        "legal_vintage": ok("vintage"),
        "legal_legacy": 1 if leg.get("legacy") == "legal" else 0,
        "legal_pauper": 1 if leg.get("pauper") == "legal" else 0,
        "edhrec_rank": c.get("edhrec_rank"),
        "game_changer": 1 if c.get("game_changer") else 0,
        "image_url": img,
        "image_back_url": back,
        "released_at": c.get("released_at"),
        "source": "scryfall",
        "updated_at": db.now(),
    }


COLS = ["key", "name", "oracle_id", "mana_cost", "cmc", "type_line", "oracle_text", "colors",
        "color_identity", "keywords", "rarity", "set_code", "collector_number", "layout",
        "legal_commander", "legal_vintage", "legal_legacy", "legal_pauper", "edhrec_rank",
        "game_changer", "image_url", "image_back_url", "released_at", "source", "updated_at"]

UPSERT = (f"INSERT INTO cards({','.join(COLS)}) VALUES({','.join('?' * len(COLS))}) "
          f"ON CONFLICT(key) DO UPDATE SET " + ",".join(f"{c}=excluded.{c}" for c in COLS if c != "key"))


def import_karten(con, path, progress=None):
    n = 0
    batch = []
    behalten = set()
    aussortiert = {}
    heute = __import__("datetime").date.today().isoformat()
    for obj, _ in eintraege(path):
        grund = aufraeumen.grund_karte(obj, heute) if obj.get("object") == "card" else None
        if grund:
            aussortiert[grund] = aussortiert.get(grund, 0) + 1
            continue
        row = card_row(obj)
        if row is None:
            continue
        behalten.add(row["key"])
        batch.append(row)
        if len(batch) >= 500:
            _flush(con, batch)
            n += len(batch)
            batch = []
            if progress:
                progress(n)
    if batch:
        _flush(con, batch)
        n += len(batch)
    if not n:
        raise RuntimeError("Die Kartendatei von Scryfall war leer.")
    # Karten, die früher geladen wurden, jetzt aber aussortiert sind (oder bei Scryfall fehlen)
    con.execute("CREATE TEMP TABLE IF NOT EXISTS _behalten (key TEXT PRIMARY KEY)")
    con.execute("DELETE FROM _behalten")
    con.executemany("INSERT OR IGNORE INTO _behalten(key) VALUES(?)", ((k,) for k in behalten))
    geloescht = con.execute(
        "DELETE FROM cards WHERE source='scryfall' AND key NOT IN (SELECT key FROM _behalten) "
        f"AND key NOT IN ({aufraeumen.geschuetzt_sql()})").rowcount
    con.execute("DROP TABLE _behalten")
    aufraeumen.bericht_speichern(con, "karten", aussortiert)
    weg = sum(aussortiert.values())
    text = f"{_zahl(n)} neu geladen, {_zahl(weg)} aussortiert"
    if geloescht:
        text += f", {_zahl(geloescht)} alte entfernt"
    return n, text


import_file = import_karten  # alter Name


def _flush(con, rows):
    con.executemany(UPSERT, [tuple(r[c] for c in COLS) for r in rows])
    for r in rows:
        db.add_aliases(con, r["key"], r["name"])


# ================================================================ Drucke (alle Felder)
DRUCK_COLS = ["id", "oracle_id", "key", "name", "lang", "printed_name", "set_code", "set_name", "set_type",
              "collector_number", "released_at", "rarity", "layout", "artist", "illustration_id",
              "illustration_id_rueck", "frame", "border_color", "full_art", "promo", "digital", "booster",
              "preis_eur", "preis_eur_foil", "preis_usd", "bild", "bild_png", "bild_art", "bild_rueck", "json"]


def _preis(v):
    try:
        return float(v) if v not in (None, "") else None
    except (TypeError, ValueError):
        return None


def _packer(zdict):
    """Komprimiert einen Druck. Das Wörterbuch (typische Feldnamen, Bild-Adressen, Legalitäten
    aus den ersten Zeilen der Datei) macht die einzelnen Einträge etwa halb so groß."""
    def packen(text):
        c = zlib.compressobj(6, zlib.DEFLATED, 15, 9, zlib.Z_DEFAULT_STRATEGY, zdict) if zdict else zlib.compressobj(6)
        return c.compress(text.encode("utf-8")) + c.flush()
    return packen


_ZDICT = {"v": None, "d": None}


def _entpacken(con, blob):
    roh = db.meta_get(con, "drucke_zdict") or ""
    if _ZDICT["v"] != roh:
        _ZDICT.update(v=roh, d=base64.b64decode(roh) if roh else None)
    try:
        d = zlib.decompressobj(zdict=_ZDICT["d"]) if _ZDICT["d"] else zlib.decompressobj()
        return d.decompress(blob) + d.flush()
    except zlib.error:
        return zlib.decompress(blob)


def druck_row(c, roh=None, packen=None):
    if c.get("object") != "card" or not c.get("id"):
        return None
    faces = _faces(c)
    f0 = faces[0] if faces else {}
    f1 = faces[1] if len(faces) > 1 else {}
    bilder = c.get("image_uris") or f0.get("image_uris") or {}
    rueck = f1.get("image_uris") or {}
    preise = c.get("prices") or {}
    name = c.get("name") or ""
    gedruckt = c.get("printed_name") or (" // ".join(f.get("printed_name") for f in faces if f.get("printed_name")) or None)
    roh = roh if roh is not None else json.dumps(c, ensure_ascii=False, separators=(",", ":"))
    return (
        c["id"], c.get("oracle_id") or f0.get("oracle_id"), db.norm(name), name, c.get("lang"), gedruckt,
        c.get("set"), c.get("set_name"), c.get("set_type"), c.get("collector_number"), c.get("released_at"),
        c.get("rarity"), c.get("layout"), c.get("artist") or f0.get("artist"),
        c.get("illustration_id") or f0.get("illustration_id"), f1.get("illustration_id"),
        c.get("frame"), c.get("border_color"), int(bool(c.get("full_art"))), int(bool(c.get("promo"))),
        int(bool(c.get("digital"))), int(bool(c.get("booster"))),
        _preis(preise.get("eur")), _preis(preise.get("eur_foil")), _preis(preise.get("usd")),
        bilder.get("normal"), bilder.get("png"), bilder.get("art_crop"), rueck.get("normal"),
        (packen or _packer(None))(roh),
    )


def import_drucke(con, path, progress=None):
    con.execute("DELETE FROM drucke")
    sql = f"INSERT OR REPLACE INTO drucke({','.join(DRUCK_COLS)}) VALUES({','.join('?' * len(DRUCK_COLS))})"
    n = 0
    batch = []
    sprachen = set()
    aussortiert = {}
    gueltig = {r[0] for r in con.execute("SELECT oracle_id FROM cards WHERE oracle_id IS NOT NULL")}
    quelle = ((o, r) for o, r in eintraege(path) if _druck_ok(o, gueltig, aussortiert))
    erste = list(itertools.islice(quelle, 40))
    zdict = "\n".join(r if r is not None else json.dumps(o, ensure_ascii=False, separators=(",", ":"))
                      for o, r in erste).encode("utf-8")[-32768:]
    packen = _packer(zdict)
    db.meta_set(con, "drucke_zdict", base64.b64encode(zdict).decode("ascii"))
    for obj, roh in itertools.chain(erste, quelle):
        row = druck_row(obj, roh, packen)
        if row is None:
            continue
        sprachen.add(row[4])
        batch.append(row)
        if len(batch) >= 2000:
            con.executemany(sql, batch)
            n += len(batch)
            batch = []
            if progress:
                progress(n)
    if batch:
        con.executemany(sql, batch)
        n += len(batch)
    if not n:
        raise RuntimeError("Die Druckdatei von Scryfall war leer.")
    db.meta_set(con, "drucke_sprachen", len(sprachen))
    aufraeumen.bericht_speichern(con, "drucke", aussortiert)
    return n, f"{_zahl(n)} neu geladen, {_zahl(sum(aussortiert.values()))} aussortiert"


def _druck_ok(obj, gueltig, aussortiert):
    if obj.get("object") != "card":
        return False
    grund = aufraeumen.grund_druck(obj)
    if not grund:
        oid = obj.get("oracle_id") or ((obj.get("card_faces") or [{}])[0].get("oracle_id"))
        if oid not in gueltig:
            grund = "karte"   # gehört zu einer aussortierten Karte (Standardland, Spaßkarte ...)
    if grund:
        aussortiert[grund] = aussortiert.get(grund, 0) + 1
        return False
    return True


def druck_json(con, druck_id):
    """Das vollständige Scryfall-Objekt eines Drucks."""
    row = con.execute("SELECT json FROM drucke WHERE id=?", (druck_id,)).fetchone()
    return json.loads(_entpacken(con, row[0]).decode("utf-8")) if row else None


# ================================================================ Tags (Scryfall-Tagger)
def import_tags(con, path, typ, progress=None):
    """typ: 'oracle' (Funktions-Tags, Ziel = oracle_id) oder 'illustration' (Bild-Tags, Ziel = illustration_id)."""
    con.execute("DELETE FROM sf_taggings WHERE tag IN (SELECT nr FROM sf_tags WHERE typ=?)", (typ,))
    con.execute("DELETE FROM sf_tags WHERE typ=?", (typ,))
    n_tags = n_zu = 0
    for obj, _ in eintraege(path):
        if obj.get("object") != "tag" or not obj.get("id"):
            continue
        cur = con.execute(
            "INSERT OR IGNORE INTO sf_tags(id,label,typ,beschreibung,eltern,aliase) VALUES(?,?,?,?,?,?)",
            (obj["id"], obj.get("label") or obj.get("slug"), typ, obj.get("description"),
             json.dumps(obj.get("parent_ids") or []), ",".join(obj.get("aliases") or [])))
        if not cur.rowcount:
            continue
        nr = cur.lastrowid
        zeilen = []
        for g in obj.get("taggings") or []:
            ziel = g.get("oracle_id") or g.get("illustration_id")
            if ziel:
                w = g.get("weight")
                zeilen.append((nr, ziel, None if w in (None, "median") else w))
        con.executemany("INSERT OR IGNORE INTO sf_taggings(tag,ziel,gewicht) VALUES(?,?,?)", zeilen)
        n_tags += 1
        n_zu += len(zeilen)
        if progress and n_tags % 500 == 0:
            progress(n_tags)
    if not n_tags:
        raise RuntimeError("Die Tag-Datei von Scryfall war leer.")
    return n_tags, f"{_zahl(n_tags)} neu geladen ({_zahl(n_zu)} Zuordnungen)"


def tag_ziele(con, labels, typ="oracle", ohne=()):
    """Alle oracle_ids (bzw. illustration_ids) mit einem der Tags – Unter-Tags eingeschlossen.
    ohne: Tags, deren Zweig nicht mitzählen soll (z.B. 'sweeper' bei 'removal')."""
    tags = con.execute("SELECT nr, id, label, eltern FROM sf_tags WHERE typ=?", (typ,)).fetchall()
    if not tags:
        return set()
    nr_von_id = {t["id"]: t["nr"] for t in tags}
    nr_von_label = {t["label"]: t["nr"] for t in tags}
    kinder = {}
    for t in tags:
        for p in json.loads(t["eltern"] or "[]"):
            if p in nr_von_id:
                kinder.setdefault(nr_von_id[p], []).append(t["nr"])

    def zweig(start):
        gesehen, offen = set(), [start]
        while offen:
            x = offen.pop()
            if x in gesehen:
                continue
            gesehen.add(x)
            offen.extend(kinder.get(x, []))
        return gesehen

    weg = set()
    for l in ohne:
        if l in nr_von_label:
            weg |= zweig(nr_von_label[l])
    nummern = set()
    for l in labels:
        if l in nr_von_label:
            nummern |= zweig(nr_von_label[l])
    nummern -= weg
    if not nummern:
        return set()
    ziele = set()
    liste = list(nummern)
    for i in range(0, len(liste), 500):
        teil = liste[i:i + 500]
        ziele.update(r[0] for r in con.execute(
            f"SELECT ziel FROM sf_taggings WHERE tag IN ({','.join('?' * len(teil))})", teil))
    return ziele


# ================================================================ Regelhinweise
def import_regeln(con, path, progress=None):
    con.execute("DELETE FROM regeln")
    n = 0
    batch = []
    for obj, _ in eintraege(path):
        if obj.get("object") != "ruling":
            continue
        batch.append((obj.get("oracle_id"), obj.get("published_at"), obj.get("source"), obj.get("comment")))
        if len(batch) >= 5000:
            con.executemany("INSERT INTO regeln(oracle_id,datum,quelle,text) VALUES(?,?,?,?)", batch)
            n += len(batch)
            batch = []
            if progress:
                progress(n)
    if batch:
        con.executemany("INSERT INTO regeln(oracle_id,datum,quelle,text) VALUES(?,?,?,?)", batch)
        n += len(batch)
    return n, f"{_zahl(n)} neu geladen"


# ================================================================ Gesamtablauf
def teile(con):
    """(Schlüssel, Bulk-Typ, Anzeigename, Importfunktion) in Ladereihenfolge."""
    return [
        ("karten", "oracle_cards", "Karten", import_karten),
        ("drucke", "default_cards", "Drucke", import_drucke),
        ("funktions_tags", "oracle_tags", "Funktions-Tags", lambda c, p, pr: import_tags(c, p, "oracle", pr)),
        ("bild_tags", "art_tags", "Bild-Tags", lambda c, p, pr: import_tags(c, p, "illustration", pr)),
        ("regeln", "rulings", "Regelhinweise", import_regeln),
    ]


def alles_da(con):
    """Sind alle Teile schon einmal geladen und nach den aktuellen Regeln aufgeräumt worden?"""
    if db.meta_get(con, "bereinigung") != aufraeumen.VERSION:
        return False
    for schluessel, typ, _, _ in teile(con):
        stand = db.meta_get(con, f"scryfall_stand_{schluessel}") or ""
        if not stand.startswith(typ + "|"):
            return False
    return True


def _zahl(n):
    return f"{n:,}".replace(",", ".")


def update(con, force=False, max_age_days=7, progress=None):
    """Prüft, ob Scryfall neue Daten hat, und lädt jeden Teil, der sich geändert hat.

    progress(phase, wert, gesamt, was) mit phase in {"pruefen","download","import"}.
    Rückgabe: {"neu": bool (Karten neu), "teile": [{teil, ok, neu, text}], ...}
    """
    p = progress or (lambda *a: None)
    geladen = float(db.meta_get(con, "scryfall_loaded_at", 0) or 0)
    if not force and geladen and db.now() - geladen < max_age_days * 86400 and alles_da(con):
        return {"neu": False, "stand": db.meta_get(con, "scryfall_updated_at"), "karten": None, "teile": [],
                "grund": f"letzte Prüfung jünger als {max_age_days} Tage"}
    p("pruefen", 0, 0, "")
    try:
        liste = bulk_liste()
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
        raise RuntimeError(f"Scryfall ist nicht erreichbar ({getattr(e, 'reason', e)}). "
                           f"Die vorhandenen Daten bleiben unverändert.") from None
    os.makedirs(SF_DIR, exist_ok=True)
    neu_filtern = db.meta_get(con, "bereinigung") != aufraeumen.VERSION
    ergebnis = []
    karten_neu, karten_n, karten_stand = False, None, None
    for schluessel, typ, name, importieren in teile(con):
        item = liste.get(typ)
        if not item:
            ergebnis.append({"teil": name, "schluessel": schluessel, "ok": False, "neu": False,
                             "text": f"bei Scryfall nicht gefunden (Typ {typ})"})
            continue
        stand = item.get("updated_at") or ""
        merk = f"{typ}|{stand}"
        if neu_filtern and schluessel in ("karten", "drucke"):
            pass  # Regeln fürs Aussortieren haben sich geändert: neu laden und filtern
        elif not force and db.meta_get(con, f"scryfall_stand_{schluessel}") == merk:
            ergebnis.append({"teil": name, "schluessel": schluessel, "ok": True, "neu": False, "text": "aktuell"})
            continue
        ziel = os.path.join(SF_DIR, f"{typ}.jsonl.gz")
        try:
            groesse = item.get("compressed_size") or item.get("size") or 0
            download(bulk_url(item), ziel, lambda d, t: p("download", d, t, name), groesse)
            p("import", 0, 0, name)
            n, text = importieren(con, ziel, lambda k: p("import", k, 0, name))
            db.meta_set(con, f"scryfall_stand_{schluessel}", merk)
            if schluessel == "karten":
                karten_neu, karten_n, karten_stand = True, n, stand
                db.meta_set(con, "scryfall_updated_at", stand)
            con.commit()
            ergebnis.append({"teil": name, "schluessel": schluessel, "ok": True, "neu": True, "text": text})
        except Exception as e:  # noqa: BLE001
            con.rollback()
            if isinstance(e, (urllib.error.URLError, TimeoutError, OSError)):
                text = f"Download abgebrochen ({getattr(e, 'reason', e)})"
            elif isinstance(e, RuntimeError):
                text = str(e)
            else:
                text = f"{type(e).__name__}: {e}"
            ergebnis.append({"teil": name, "schluessel": schluessel, "ok": False, "neu": False, "text": text,
                             "details": traceback.format_exc()})
        finally:
            for pfad in (ziel, ziel + ".part"):
                try:
                    os.remove(pfad)
                except OSError:
                    pass
    if any(x.get("neu") for x in ergebnis):
        p("aufraeumen", 0, 0, "")
        aufraeumen.nachbereinigen(con)
    if all(x["ok"] for x in ergebnis):
        db.meta_set(con, "scryfall_loaded_at", db.now())
        db.meta_set(con, "bereinigung", aufraeumen.VERSION)
    con.commit()
    if any(x.get("neu") for x in ergebnis):
        aufraeumen.platz_freigeben(con)
        try:
            con.execute("PRAGMA wal_checkpoint(TRUNCATE)")
        except Exception:  # noqa: BLE001
            pass
    if not ergebnis[0]["ok"] and not con.execute("SELECT COUNT(*) FROM cards WHERE source='scryfall'").fetchone()[0]:
        fehler = RuntimeError(f"Karten: {ergebnis[0]['text']}")
        fehler.teile = ergebnis
        raise fehler
    return {"neu": karten_neu, "stand": karten_stand or db.meta_get(con, "scryfall_updated_at"),
            "karten": karten_n, "teile": ergebnis}

turnier.py:
"""Turnierdaten von MTGGoldfish: Welche Karten in Vintage-, Legacy- und Duel-Commander-Decks gespielt werden.

MTGGoldfish zeigt für jedes Format die 50 meistgespielten Karten, Kreaturen, Sprüche und Länder
(„Format Staples“, mit Anteil der Decks). Für den Generator ist das ein Stärke-Signal, das schneller ist
als die Draft-Elo: Neue Karten wie Bilbo, Thief in the Night oder Quantum Riddler tauchen dort auf,
lange bevor genug Cube-Drafts sie bewertet haben.

  * Vintage-Cubes: der höhere Anteil aus Vintage und Legacy.
  * Commander-Cubes: Duel Commander (1 gegen 1, also eher ein Zeichen roher Stärke).
Ein Stand liegt bei (turnier_start.json); das Programm holt jede Woche den aktuellen.
"""
import html
import json
import os
import re
import time
import urllib.error
import urllib.request

from . import db

URL = "https://www.mtggoldfish.com/format-staples/{fmt}/full/{teil}"
FORMATE = ["vintage", "legacy", "duel_commander"]
TEILE = ["all", "creatures", "spells", "lands"]
START = os.path.join(os.path.dirname(os.path.abspath(__file__)), "turnier_start.json")
USER_AGENT = "CubeGenerator/1.3 (privates Cube-Tool)"
_ZEILE = re.compile(r"<tr[^>]*>(.*?)</tr>", re.S)
_NAME = re.compile(r'<td class="col-card">.*?<a [^>]*>([^<]+)</a>', re.S)
_ZAHLEN = re.compile(r'<td class="text-end">\s*([\d.]+)(%?)\s*</td>')


def _seite(fmt, teil, timeout=30):
    req = urllib.request.Request(URL.format(fmt=fmt, teil=teil),
                                 headers={"User-Agent": USER_AGENT, "Accept": "text/html"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode("utf-8", "replace")


def auslesen(text):
    """[(Name, Anteil in %, Kopien)] aus einer Format-Staples-Seite."""
    out = []
    for zeile in _ZEILE.findall(text):
        m = _NAME.search(zeile)
        if not m:
            continue
        zahlen = _ZAHLEN.findall(zeile)
        pct = next((float(z) for z, p in zahlen if p), None)
        kopien = float(zahlen[-1][0]) if zahlen and not zahlen[-1][1] else 1.0
        if pct is not None:
            out.append((html.unescape(m.group(1)).strip(), pct, kopien))
    return out


def _speichern(con, daten, stand, quelle):
    """daten: {Format: [(Name, Prozent, Kopien)]}"""
    zeilen = {}
    for fmt, eintraege in daten.items():
        for name, pct, kopien in eintraege:
            k = db.resolve(con, name)
            if not k:
                continue
            alt = zeilen.get((fmt, k))
            if not alt or alt[0] < pct:
                zeilen[(fmt, k)] = (pct / 100.0, kopien)
    if not zeilen:
        return 0
    con.execute("DELETE FROM turnier")
    con.executemany("INSERT INTO turnier(format, key, anteil, kopien) VALUES(?,?,?,?)",
                    [(f, k, a, c) for (f, k), (a, c) in zeilen.items()])
    db.meta_set(con, "turnier_stand", stand)
    db.meta_set(con, "turnier_quelle", quelle)
    con.commit()
    return len(zeilen)


def aus_start(con, erzwingen=False):
    """Mitgelieferten Stand übernehmen, wenn noch nichts da ist."""
    if not erzwingen and con.execute("SELECT 1 FROM turnier LIMIT 1").fetchone():
        return 0
    if not os.path.exists(START) or not con.execute("SELECT 1 FROM cards LIMIT 1").fetchone():
        return 0
    with open(START, encoding="utf-8") as f:
        d = json.load(f)
    daten = {fmt: [tuple(e) for e in eintr] for fmt, eintr in d["formate"].items()}
    return _speichern(con, daten, d.get("stand"), "mitgeliefert")


def laden(con, progress=None, pause=1.0):
    """Holt die aktuellen Format Staples von MTGGoldfish (12 Seiten)."""
    p = progress or (lambda *a: None)
    daten, fehler = {}, []
    schritte = [(f, t) for f in FORMATE for t in TEILE]
    for i, (fmt, teil) in enumerate(schritte):
        p("turnier", i, len(schritte), f"{fmt} {teil}")
        try:
            daten.setdefault(fmt, []).extend(auslesen(_seite(fmt, teil)))
        except (urllib.error.URLError, TimeoutError, OSError, ValueError) as e:
            fehler.append(f"{fmt}/{teil}: {getattr(e, 'code', '') or getattr(e, 'reason', e)}")
            if len(fehler) >= 3 and not any(daten.values()):
                aus_start(con)
                raise RuntimeError("MTGGoldfish lässt das Programm gerade nicht herein – es bleibt beim letzten Stand.") from None
        time.sleep(pause)
    if not any(daten.values()):
        raise RuntimeError("Von MTGGoldfish kamen keine Daten.")
    n = _speichern(con, daten, time.strftime("%Y-%m-%d"), "MTGGoldfish")
    db.meta_set(con, "turnier_at", db.now())
    con.commit()
    return {"karten": n, "fehler": fehler}


def anteile(con):
    """{key: {"vintage": 0.28, "legacy": 0.07, "duel_commander": 0.4}}"""
    out = {}
    try:
        for fmt, k, a in con.execute("SELECT format, key, anteil FROM turnier"):
            out.setdefault(k, {})[fmt] = a
    except Exception:  # noqa: BLE001
        return {}
    return out


def fuer_format(werte, fmt):
    """Der Turnier-Anteil, der für dieses Cube-Format zählt (0..1)."""
    if not werte:
        return 0.0
    if fmt == "commander":
        return werte.get("duel_commander", 0.0)
    return max(werte.get("vintage", 0.0), werte.get("legacy", 0.0))
